'use client'
import { useState, useEffect, useRef, use } from 'react'
import { supabase } from '../../../lib/supabase'

const freeQuestions: Record<string, any[]> = {

  // ─── PPL ────────────────────────────────────────────────────
  'PPL Theory': [
    { question: 'What is pressure altitude and how is it calculated from field elevation and QNH?', options: ['A. The height shown on the altimeter set to QFE', 'B. Field elevation + (1013 - QNH hPa) x 27 ft — used as the input for performance charts', 'C. Pressure altitude equals density altitude at standard temperature', 'D. The altitude shown when QNH is set on the altimeter'], correct: 1, explanation: 'Pressure altitude = field elevation + (1013.25 - QNH) x ~27 ft per hPa. Example: elevation 500 ft, QNH 998 hPa: PA = 500 + (1013-998) x 27 = 905 ft. Performance charts use pressure altitude not field elevation. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / RPL PPL CPL Workbook' },
    { question: 'What is density altitude and how does it affect aircraft performance?', options: ['A. Density altitude is the same as pressure altitude', 'B. Density altitude = pressure altitude + 120 x (OAT - ISA temp). High density altitude means less dense air — reduced engine power, propeller thrust, and aerodynamic lift, increasing TODR and reducing climb performance', 'C. Density altitude only affects jet aircraft', 'D. Density altitude decreases with higher temperature'], correct: 1, explanation: 'DA = PA + 120 x (OAT - ISA OAT). ISA at sea level = 15°C, reducing 2°C per 1000 ft. Hot day at high elevation = very high density altitude = severely degraded performance. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / RPL PPL CPL Workbook' },
    { question: 'An aircraft has MTOW 1300 kg, BEW 820 kg, fuel 130 kg, pilot 85 kg. What is the maximum passenger and baggage weight?', options: ['A. 265 kg', 'B. 350 kg', 'C. 480 kg', 'D. 195 kg'], correct: 0, explanation: 'Maximum payload = MTOW - BEW - Fuel - Pilot = 1300 - 820 - 130 - 85 = 265 kg. This is the maximum combined weight for passengers and baggage.', reference: 'CASA PPLA Syllabus / RPL PPL CPL Workbook' },
    { question: 'What does the TEMPO group in a TAF mean?', options: ['A. A permanent change lasting more than 4 hours', 'B. Temporary conditions expected to last less than 1 hour each occurrence, total less than half the forecast period', 'C. Temperature forecast for the aerodrome', 'D. A terminal observation not a forecast'], correct: 1, explanation: 'TEMPO indicates temporary fluctuations expected to last less than 1 hour at a time, and in total less than half the period described. The conditions may reduce below the prevailing forecast values during TEMPO periods. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / AIP GEN 3.5 / BOM TAF Guide' },
    { question: 'A flight departs at 0915 and the planned trip time is 1 hour 50 minutes. At the halfway point the actual time is 1015. Is the aircraft ahead or behind schedule?', options: ['A. Exactly on schedule', 'B. 5 minutes ahead of schedule', 'C. 5 minutes behind schedule', 'D. 10 minutes behind schedule'], correct: 1, explanation: 'Planned halfway time = 0915 + 55 min = 1010. Actual time at halfway = 1015. Difference = 5 minutes late. However at the halfway point the aircraft is running 5 minutes behind, meaning it could be ahead if speed is maintained — but strictly it arrived at the halfway point 5 minutes late. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / Navigation Study Guide' },
    { question: 'What is the minimum fuel for a VFR day flight under Part 91, trip time 1h 40min, fuel burn 48 L/hr?', options: ['A. 80 litres', 'B. 116 litres', 'C. 96 litres', 'D. 60 litres'], correct: 1, explanation: 'Trip fuel = 48 x 1.667 = 80 L. Reserve (45 min) = 48 x 0.75 = 36 L. Total = 80 + 36 = 116 L. Under Part 91 VFR day piston under 5700 kg: trip fuel + 45 min reserve.', reference: 'CASR Part 91 MOS Chapter 19 / CAO 20.9' },
    { question: 'What is the standard traffic circuit direction at a non-controlled aerodrome?', options: ['A. Right hand always', 'B. Left hand unless otherwise published in ERSA or by NOTAM', 'C. Pilot discretion based on wind', 'D. Determined by runway orientation only'], correct: 1, explanation: 'The standard circuit is LEFT HAND unless a right-hand circuit is published in ERSA, shown on charts, or specified by NOTAM. Always check ERSA before flying to an unfamiliar aerodrome.', reference: 'AIP ENR 1.1 / ERSA' },
    { question: 'What does the BECMG group in a TAF indicate?', options: ['A. A temporary deterioration in conditions', 'B. A permanent change in conditions expected to occur gradually and be complete within the specified period', 'C. Becoming — same as TEMPO but lasting longer', 'D. Conditions expected to begin at the end of the forecast period'], correct: 1, explanation: 'BECMG (becoming) indicates conditions are expected to change gradually and be fully established by the end of the specified period. Unlike TEMPO, BECMG changes are permanent for the remainder of the forecast. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / AIP GEN 3.5' },
    { question: 'What is the effect of a downslope runway on landing distance required?', options: ['A. Downslope reduces LDR as gravity assists stopping', 'B. Downslope increases LDR as gravity acts in the direction of travel, reducing braking effectiveness', 'C. Runway slope has no effect on LDR', 'D. Only upslope affects LDR'], correct: 1, explanation: 'A downsloping runway increases LDR because gravity opposes deceleration. The CASA workbook correction is approximately 5% increase per 1% of downslope. An upsloping runway decreases LDR as gravity assists braking. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / RPL PPL CPL Workbook / AC 91-02' },
    { question: 'What is the ALPHA loading system used in the CASA workbook?', options: ['A. ALPHA uses actual moments in kg.m for CG calculation', 'B. ALPHA uses reduced index numbers (moment/constant) for each loading station — the total index is plotted against total weight on a loading chart to verify CG is within limits', 'C. ALPHA only applies to aircraft over 2000 kg', 'D. ALPHA and BRAVO loading systems are identical'], correct: 1, explanation: 'The ALPHA loading system uses simplified index values (moments divided by a reduction factor) to make CG calculations manageable. The total loaded index and total weight are plotted on the loading envelope chart. The plotted point must fall within the approved CG envelope. A common weak area in PPLA.', reference: 'CASA PPLA Syllabus / RPL PPL CPL Workbook' },
  ],

  // ─── CPL ────────────────────────────────────────────────────
  'Human Factors': [
    { question: 'Which part of the eye is responsible for colour vision and fine detail in daylight?', options: ['A. Rods in the peripheral retina', 'B. Cones concentrated in the fovea centralis', 'C. The optic nerve at the macula', 'D. The iris and ciliary muscle'], correct: 1, explanation: 'Cones are concentrated in the fovea centralis and provide colour vision and high-resolution detail in good lighting. Rods are used for peripheral and night vision. A common weak area in CHUF.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'A pilot on approach sees a runway that appears narrower than usual. What illusion is this and what is the likely result?', options: ['A. Upsloping runway — pilot flies high', 'B. Narrow runway illusion — pilot perceives being too high and flies a dangerously low approach', 'C. Featureless terrain — pilot flies level', 'D. Wide runway — pilot flies high'], correct: 1, explanation: 'A narrower than normal runway creates the illusion the aircraft is higher than it actually is, causing the pilot to fly a dangerously low approach. Visual illusions on approach are a common weak area in CHUF.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'What is Threat and Error Management (TEM)?', options: ['A. A checklist system for managing ATC threats', 'B. A framework describing how crews manage threats beyond their control, errors they make, and undesired aircraft states that result', 'C. A method of reporting errors to CASA', 'D. A procedure for managing automation errors only'], correct: 1, explanation: 'TEM is an ICAO framework with three tiers: threats (external factors beyond crew control), errors (crew deviations from intentions), and undesired aircraft states (crew-induced positions, speeds, or configurations reducing safety margins).', reference: 'CASA CHUF Syllabus / ICAO Doc 9683' },
    { question: 'What is the function of the semicircular canals?', options: ['A. They detect linear acceleration and gravity', 'B. They detect angular acceleration and rotational motion in three planes', 'C. They control balance only when stationary', 'D. They detect sound vibrations'], correct: 1, explanation: 'The three semicircular canals detect angular acceleration (rotation) in three planes. They can be deceived during sustained turns in IMC, leading to spatial disorientation and the graveyard spiral.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'What are the effects of fatigue on pilot performance?', options: ['A. Improved focus through adrenaline', 'B. Degraded decision-making, increased reaction time, reduced vigilance, and impaired communication — pilots may not recognise their own impairment', 'C. Only physical effects, cognitive performance is unaffected', 'D. Fatigue only affects performance after 24 hours without sleep'], correct: 1, explanation: 'Fatigue degrades all aspects of performance including decision-making, reaction time, vigilance, communication, and memory. Pilots are often the last to recognise their own fatigue impairment.', reference: 'CAO 48.1 / CASA CHUF Syllabus' },
    { question: 'What does IMSAFE stand for?', options: ['A. Instruments, Maps, Systems, Airworthiness, Fuel, Emergency', 'B. Illness, Medication, Stress, Alcohol, Fatigue, Emotion', 'C. IFR, Meteorology, Systems, Alternates, Fuel, Equipment', 'D. Inspection, Maintenance, Safety, Airspace, Fuel, Experience'], correct: 1, explanation: 'IMSAFE is a personal minimums checklist: Illness, Medication, Stress, Alcohol, Fatigue, Emotion. Used before every flight to assess personal fitness to fly.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'What is the primary physiological effect of carbon monoxide poisoning?', options: ['A. It increases oxygen carrying capacity', 'B. It binds to haemoglobin with 250x the affinity of oxygen, reducing oxygen delivery and causing hypoxia-like symptoms', 'C. It causes immediate loss of consciousness', 'D. It primarily affects the vestibular system'], correct: 1, explanation: 'Carbon monoxide binds to haemoglobin with approximately 250 times the affinity of oxygen, forming carboxyhaemoglobin. Symptoms (headache, dizziness, impaired judgement) resemble hypoxia and can be insidious.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'What is the dark adaptation time required for full night vision?', options: ['A. 5 minutes', 'B. 10 minutes', 'C. 30 minutes', 'D. 45 minutes'], correct: 2, explanation: 'Full dark adaptation takes approximately 30 minutes. Rod cells (responsible for night vision) adapt much more slowly than cone cells. Even brief exposure to bright light significantly resets dark adaptation.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
    { question: 'Which best describes get-there-itis (plan continuation bias)?', options: ['A. Overconfidence in aircraft systems', 'B. Continuing an original plan despite changing conditions that should prompt reassessment, driven by goal fixation', 'C. Lack of instrument training', 'D. Excessive GPS reliance'], correct: 1, explanation: 'Get-there-itis is driven by goal fixation — the desire to complete the intended flight overrides sound judgement when conditions deteriorate. It is a leading cause of VFR into IMC accidents in Australia.', reference: 'CASA CHUF Syllabus / ATSB Safety Research' },
    { question: 'What is the somatogravic illusion and when does it occur?', options: ['A. A false banking sensation during coordinated turns', 'B. During rapid acceleration the otoliths interpret forward acceleration as nose-up pitch — the pilot may push forward to correct the false nose-high sensation, risking CFIT', 'C. A false rolling sensation caused by semicircular canals', 'D. An illusion caused by looking at the ground in a steep turn'], correct: 1, explanation: 'The somatogravic illusion occurs during rapid acceleration (go-around, takeoff in IMC). The otoliths cannot distinguish forward acceleration from nose-up pitch, causing the pilot to feel nose-high and potentially push forward — extremely dangerous at low altitude.', reference: 'CASA CHUF Syllabus / Human Factors Study Guide' },
  ],

  'Aerodynamics': [
    { question: 'What is the function of a vortex generator?', options: ['A. To increase induced drag at high AoA', 'B. To re-energise the boundary layer by mixing high-energy air from above, delaying flow separation and stall', 'C. To reduce parasite drag in cruise', 'D. To generate additional lift at low speeds'], correct: 1, explanation: 'Vortex generators create small vortices that re-energise the boundary layer, delaying flow separation. This improves low-speed handling and stall characteristics. A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is ground effect and how does it affect takeoff?', options: ['A. Ground effect increases induced drag near the ground', 'B. Ground effect reduces induced drag by up to 50% within one wingspan of the ground — the aircraft can fly at speeds below its out-of-ground-effect stall speed, creating a dangerous departure situation', 'C. Ground effect has no significant impact on takeoff', 'D. Ground effect increases stall speed near the ground'], correct: 1, explanation: 'Ground effect interrupts wingtip vortex formation, reducing induced drag by up to 50%. An aircraft can fly in ground effect below its normal stall speed — dangerous if it climbs out of ground effect before reaching a safe speed. A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is wing washout?', options: ['A. Increased angle of incidence toward the wingtip', 'B. A progressive reduction in angle of incidence from root to tip — ensures the root stalls before the tip, maintaining aileron effectiveness at the stall', 'C. A cleaning process for the wing surface', 'D. A reduction in wing area toward the tip'], correct: 1, explanation: 'Washout (geometric twist) reduces angle of incidence from root to tip. The root reaches the critical angle of attack first, stalling before the tip. This maintains aileron effectiveness throughout the stall and provides natural stall warning. A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'An aircraft has a stall speed of 55 knots clean. What is the stall speed in a 60 degree banked level turn?', options: ['A. 55 knots', 'B. 67 knots', 'C. 78 knots', 'D. 90 knots'], correct: 2, explanation: 'At 60 degrees bank, load factor = 1/cos(60) = 2G. New stall speed = 55 x √2 = 55 x 1.414 = 77.8 ≈ 78 knots. Load factor increases stall speed by the square root of the load factor.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is the best range speed for a piston aircraft?', options: ['A. The speed of minimum power required (Vmp)', 'B. The speed of minimum drag (Vmd) giving maximum L/D ratio', 'C. Normal cruise power as per POH', 'D. Vy (best rate of climb)'], correct: 1, explanation: 'Best range for a piston aircraft is at Vmd (minimum drag speed) which gives maximum lift-to-drag ratio. At this speed, fuel burned per nautical mile is minimised. Vmd is faster than Vmp (best endurance speed). A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is the best endurance speed?', options: ['A. The same as best range speed', 'B. The speed of minimum power required (Vmp) — slower than best range speed, minimises fuel burned per hour', 'C. Maximum lift-to-drag ratio speed', 'D. The speed at which fuel flow is minimum regardless of airspeed'], correct: 1, explanation: 'Best endurance is at Vmp (minimum power required). At this speed the engine burns the least fuel per hour, maximising time aloft. Vmp is slower than Vmd (best range). A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'How does anhedral affect lateral stability?', options: ['A. Anhedral increases lateral stability', 'B. Anhedral reduces lateral stability — used on aircraft that would otherwise have excessive dihedral effect such as swept-wing or high-wing aircraft', 'C. Anhedral has no effect on lateral stability', 'D. Anhedral increases roll rate at all speeds'], correct: 1, explanation: 'Anhedral (wings angled downward from root to tip) reduces the natural dihedral effect. It counteracts excessive lateral stability common in swept-wing and high-wing designs. A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is the effect of a spoiler in flight?', options: ['A. Spoilers increase lift and reduce drag', 'B. Spoilers disrupt airflow over the wing reducing lift and increasing drag simultaneously — used for roll control and speed braking', 'C. Spoilers only affect drag with no lift effect', 'D. Spoilers only work at low speed'], correct: 1, explanation: 'Spoilers disrupt smooth airflow over the upper wing surface, simultaneously reducing lift and increasing drag. Asymmetric deployment provides roll control on swept-wing aircraft. Symmetric deployment provides speed braking. A common weak area in CADA.', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
    { question: 'What is Va and why does it decrease with weight?', options: ['A. Va increases as weight decreases', 'B. Va decreases as weight decreases — lighter aircraft stall at lower speeds, so the aircraft will stall (safely) before reaching the structural limit load factor at a lower speed', 'C. Va remains constant regardless of weight', 'D. Va only changes with altitude'], correct: 1, explanation: 'Va is the speed at which the aircraft will stall before exceeding the structural limit load factor if full control deflection is applied. Since stall speed decreases with weight, Va also decreases. Always check the AFM for Va at different weights.', reference: 'CASA CADA Syllabus / Aircraft Flight Manual' },
    { question: 'What is P-factor (asymmetric blade effect)?', options: ['A. The tendency for the aircraft to pitch nose-up at high power', 'B. At high angles of attack, the descending propeller blade has a greater effective AoA and generates more thrust, causing a yawing moment toward the low blade (to the left for standard rotation)', 'C. Power factor reduction at altitude', 'D. Pitching moment from gyroscopic precession'], correct: 1, explanation: 'P-factor occurs at high angles of attack when the descending blade (right side for clockwise rotation viewed from behind) has a higher effective angle of attack, generating more thrust on that side and causing a yaw to the left. Most significant at high power and low speed (takeoff).', reference: 'CASA CADA Syllabus / Aerodynamics Study Guide' },
  ],

  'Aircraft General Knowledge': [
    { question: 'What does a HIGH positive ammeter reading immediately after engine start indicate?', options: ['A. Battery is fully charged', 'B. Normal — the alternator is recharging the battery depleted during start. A ZERO reading indicates the alternator is not charging', 'C. Electrical fault requiring immediate shutdown', 'D. Overvoltage condition'], correct: 1, explanation: 'After engine start, a high positive ammeter is NORMAL — the alternator is recharging the battery. Once recharged the reading reduces to reflect actual electrical load. A zero reading indicates the alternator/generator is not charging — an abnormal indication requiring investigation. A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What is the correct indication when carburettor heat is applied and ice IS present?', options: ['A. Immediate RPM increase', 'B. Initial RPM drop then a RPM rise as the ice melts', 'C. No RPM change', 'D. Immediate engine shutdown'], correct: 1, explanation: 'When carb heat is applied and ice is present: RPM initially drops further (less dense hot air) then RISES as ice melts. If no ice is present, RPM drops and stays down. A rough-running engine after carb heat application confirms ice was present and is melting. A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What are the identifying colours for AVGAS 100LL and AVGAS 100?', options: ['A. 100LL is red; 100 is blue', 'B. 100LL is blue; 100 is green', 'C. Both are colourless', 'D. 100LL is green; 100 is red'], correct: 1, explanation: 'AVGAS 100LL (low lead) is dyed BLUE. AVGAS 100 is dyed GREEN. Jet A-1 is colourless/straw-coloured and must NEVER be used in piston engines. Fuel identification is a common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'Why do piston aircraft engines have two magnetos?', options: ['A. To power aircraft avionics redundantly', 'B. Magnetos are self-contained engine-driven ignition devices — two provide complete ignition redundancy. If one fails the engine continues on the other', 'C. One magneto is for starting, the other for normal operation', 'D. To control the fuel-air mixture'], correct: 1, explanation: 'Magnetos are completely independent of the aircraft electrical system. Each fires one set of spark plugs per cylinder. Two magnetos mean the engine continues if one fails. The magneto check (RPM drop test) verifies both are working correctly. A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What is a turbocharger and how does it differ from a supercharger?', options: ['A. Both devices are identical', 'B. A turbocharger is exhaust-driven, using waste energy to compress induction air; a supercharger is mechanically driven by the engine crankshaft — turbocharger is more efficient', 'C. A turbocharger increases RPM; a supercharger increases manifold pressure', 'D. Superchargers are for low altitude only'], correct: 1, explanation: 'A turbocharger uses exhaust gas energy to spin a turbine driving a compressor. A supercharger is driven mechanically by the engine. Both maintain manifold pressure at altitude but turbochargers are more efficient as they use waste exhaust energy. A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What is the purpose of the mixture control at altitude?', options: ['A. Mixture controls fuel pressure', 'B. At altitude the air is less dense — the engine runs too rich at full rich. Leaning restores the correct fuel-air ratio, reducing roughness and fuel consumption', 'C. Mixture is only used during engine start', 'D. Rich mixture increases engine temperature only'], correct: 1, explanation: 'As altitude increases, air density decreases causing an over-rich fuel-air mixture. Symptoms: rough running, high fuel consumption, black smoke, power loss. Leaning to peak EGT or per the POH restores correct mixture. A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What instruments does the aircraft vacuum system power?', options: ['A. The vacuum system powers the fuel pump as backup', 'B. The vacuum system powers the attitude indicator and directional indicator — vacuum failure causes these to slowly become unreliable within 10-15 minutes', 'C. The vacuum system powers pitot-static instruments', 'D. The vacuum system powers the autopilot only'], correct: 1, explanation: 'The vacuum system (engine-driven pump) powers the gyroscopic attitude indicator (AI) and directional indicator (DI). The turn coordinator is electrically powered. Vacuum failure causes the AI and DI to slowly precess and become unreliable.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What are you looking for during a fuel sump drain check?', options: ['A. Correct fuel quantity only', 'B. Water contamination (clear globules or a separate lower layer), sediment, and correct fuel colour and type', 'C. Fuel checks are only required after refuelling', 'D. Only smell the fuel to verify quality'], correct: 1, explanation: 'Fuel sump checks verify: no water (appears as clear globules or a separate lower layer), no sediment, correct fuel colour (blue for AVGAS 100LL). Water does not burn and causes engine failure. Check all sump drains until consistently clean fuel is obtained.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What is the purpose of a constant-speed propeller governor?', options: ['A. It prevents the propeller exceeding maximum RPM only', 'B. The governor automatically adjusts blade pitch to maintain the RPM selected by the pilot — increases pitch when RPM rises, decreases pitch when RPM falls', 'C. It synchronises propeller RPM between engines on multi-engine aircraft only', 'D. It controls feathering during engine failure only'], correct: 1, explanation: 'The propeller governor senses actual RPM and adjusts blade pitch to maintain the selected RPM. If RPM rises (descent/increased speed), pitch increases adding load. If RPM falls (climb/reduced speed), pitch decreases reducing load. This maintains constant RPM for optimum efficiency.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
    { question: 'What magneto RPM drop is acceptable during the pre-flight magneto check?', options: ['A. Any RPM drop is acceptable', 'B. Typically maximum 125 RPM drop on either mag with no more than 50 RPM difference between the two mags', 'C. Zero drop is required — any drop indicates a fault', 'D. Up to 200 RPM drop is acceptable'], correct: 1, explanation: 'Typical magneto check limits: maximum 125 RPM drop on each mag, maximum 50 RPM difference between the two mags. An excessive drop indicates a fault (usually a fouled or dead spark plug). A zero drop on one mag may indicate the magneto is not switching off properly (p-lead failure). A common weak area in CSYA.', reference: 'CASA CSYA Syllabus / Aircraft General Knowledge Study Guide' },
  ],

  'Meteorology': [
    { question: 'When the environmental lapse rate exceeds the DALR, what is the atmospheric stability condition?', options: ['A. Stable — convection is suppressed', 'B. Absolutely unstable — displaced air parcels accelerate away, leading to vigorous convection and CB development', 'C. Conditionally unstable', 'D. Neutral equilibrium'], correct: 1, explanation: 'When the ELR exceeds the DALR (~3°C/1000 ft), the atmosphere is absolutely unstable. Displaced air parcels become warmer than surroundings and continue to rise, producing vigorous convection, CB development, and turbulence. A common weak area in CMET.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'The surface temperature is 28°C and the dewpoint is 10°C. What is the approximate cloud base?', options: ['A. 3600 ft AGL', 'B. 5400 ft AGL', 'C. 7200 ft AGL', 'D. 4800 ft AGL'], correct: 2, explanation: 'Cloud base = (Temp - Dewpoint) / 2.5 x 1000 ft = (28-10) / 2.5 x 1000 = 18/2.5 x 1000 = 7.2 x 1000 = 7200 ft AGL.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'What is a microburst and why is it dangerous on approach?', options: ['A. A large-scale downdraft from tropical cyclones', 'B. A concentrated downdraft creating outflow — aircraft on approach experience headwind increase (pilot reduces power), then downdraft, then tailwind (airspeed drops catastrophically)', 'C. A localised sea breeze windshift', 'D. Severe CAT near jet streams'], correct: 1, explanation: 'A microburst creates a classic windshear pattern: headwind increase (reducing power), intense downdraft, then tailwind (airspeed loss). The total energy loss can be catastrophic at low altitude. The event may last only 1-2 minutes. A common weak area in CMET.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'What conditions are necessary for radiation fog?', options: ['A. Strong winds, high humidity, frontal passage', 'B. Clear skies, light winds 2-5 kt, high relative humidity, long night — typically in valleys', 'C. Onshore winds over cold land', 'D. Orographic lifting over mountains'], correct: 1, explanation: 'Radiation fog requires: clear skies (no insulating cloud), light winds (mixing but not dispersing), high relative humidity, and a long night for sufficient radiative cooling. Valleys collect cold air drainage fog. A common weak area in CMET.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'What does BKN025CB in a METAR indicate?', options: ['A. Broken cloud at 25000 ft', 'B. Broken cumulonimbus at 2500 ft AAL — the CB suffix indicates the most severe cloud type', 'C. Broken cloud at 2500 ft with no significant type', 'D. Cumulonimbus base below 2500 ft'], correct: 1, explanation: 'BKN025CB: broken (5-7 oktas) cloud at 2500 ft AAL, type cumulonimbus. The CB suffix is critical — it indicates severe weather potential (turbulence, icing, lightning, hail). A METAR decoder should always note CB suffixes. A common weak area in CMET.', reference: 'CASA CMET Syllabus / AIP GEN 3.5' },
    { question: 'What does backing wind indicate in the Southern Hemisphere?', options: ['A. Backing wind indicates improving weather in the Southern Hemisphere', 'B. Backing (anticlockwise rotation) indicates deteriorating weather — associated with approaching low pressure or warm front', 'C. Backing means the wind is turning clockwise in Australia', 'D. Backing winds only occur above the tropopause'], correct: 1, explanation: 'In the Southern Hemisphere, a backing wind (turning anticlockwise — e.g. NW to W to SW) indicates deteriorating weather, typically an approaching depression or warm front. A veering wind (clockwise) indicates improving conditions. A common weak area in CMET.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'What is a Graphical Area Forecast (GAF)?', options: ['A. A point forecast for major aerodromes', 'B. A graphical forecast covering cloud, visibility, significant weather, icing, and turbulence for a geographic region and time period used for low-level flight planning', 'C. An upper winds and temperature forecast', 'D. A PIREP summary'], correct: 1, explanation: 'The GAF provides graphical weather forecasts for low-level flights (surface to FL100 or FL180). It shows cloud layers, visibility, significant weather, icing, and turbulence in defined areas. Essential for VFR and low-level IFR flight planning. A common weak area in CMET.', reference: 'CASA CMET Syllabus / BOM GAF Guide' },
    { question: 'What is density altitude and how does it affect performance?', options: ['A. Same as pressure altitude', 'B. Pressure altitude corrected for non-standard temperature — high density altitude (hot, high, humid) reduces engine power, propeller efficiency, and aerodynamic lift', 'C. Only relevant above 10000 ft', 'D. Density altitude decreases with higher temperature'], correct: 1, explanation: 'Density altitude = pressure altitude corrected for temperature above or below ISA. High density altitude means less dense air — reduced engine power, reduced propeller thrust, reduced aerodynamic lift. Critical for performance calculations on hot days at elevated aerodromes.', reference: 'CASA CMET Syllabus / Performance Study Guide' },
    { question: 'What is the effect of a temperature inversion on convection?', options: ['A. Inversions enhance convective development', 'B. Inversions act as a cap on convection — rising air parcels reach the warmer inversion layer and stop rising, limiting cloud top height', 'C. Inversions have no effect on convection', 'D. Inversions cause cloud to spread as fog'], correct: 1, explanation: 'A temperature inversion is a stable lid on convection. When a rising parcel reaches the inversion base, it becomes cooler and denser than the surrounding air and stops rising. This limits CB development on some days but when the cap breaks, explosive convection can result.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
    { question: 'What is wind shear and why is it dangerous on approach?', options: ['A. Only turbulence at high altitude', 'B. A sudden change in wind speed or direction over a short distance — on approach it causes sudden changes in airspeed and lift, potentially leading to undershoot or loss of control', 'C. Only occurs near fronts', 'D. Only affects large aircraft'], correct: 1, explanation: 'Wind shear is a sudden change in wind velocity (speed or direction) over a short distance. On approach, sudden headwind loss reduces airspeed and lift — the aircraft may undershoot. Microburst wind shear is particularly dangerous. A common weak area in CMET.', reference: 'CASA CMET Syllabus / Meteorology Study Guide' },
  ],

  'Navigation': [
    { question: 'An aircraft departs at 0915 UTC, GS 135 kt, destination 270 nm. What is the ETA?', options: ['A. 1100 UTC', 'B. 1115 UTC', 'C. 1130 UTC', 'D. 1145 UTC'], correct: 1, explanation: 'Time = 270 / 135 = 2.0 hours = 2 hours 00 minutes. ETA = 0915 + 0200 = 1115 UTC.', reference: 'CASA CNAV Syllabus / Navigation Study Guide' },
    { question: 'Using the 1-in-60 rule: 80 nm flown, 4 nm right of track. What heading change to parallel track?', options: ['A. 1 degree left', 'B. 3 degrees left', 'C. 5 degrees left', 'D. 7 degrees left'], correct: 1, explanation: 'Track error = (4/80) x 60 = 3 degrees. To parallel the planned track, apply 3 degrees correction toward the track — turn 3 degrees LEFT.', reference: 'CASA CNAV Syllabus / Navigation Study Guide' },
    { question: 'What is LSALT and what clearance does it provide?', options: ['A. 500 ft clearance within 5 nm of track', 'B. 1000 ft terrain clearance within 5 nm either side of track (10 nm in mountainous areas)', 'C. Minimum altitude for IFR flight', 'D. Altitude guaranteeing radar coverage'], correct: 1, explanation: 'LSALT provides a minimum of 1000 ft terrain and obstacle clearance within 5 nm either side of track, or 10 nm in designated mountainous areas. Calculated from topographic charts or published LSALT grids in the AIP.', reference: 'CASA CNAV Syllabus / AIP ENR 1.1' },
    { question: 'What is the required ROC to maintain a 5% gradient at 120 kt GS?', options: ['A. 600 ft/min', 'B. 800 ft/min', 'C. 1000 ft/min', 'D. 1200 ft/min'], correct: 2, explanation: 'ROC (ft/min) = GS (kt) x gradient (%) / 0.6 = 120 x 5 / 0.6 = 1000 ft/min. This formula is used for departure and approach climb gradient compliance. A common weak area in CNAV.', reference: 'CASA CNAV Syllabus / Navigation Study Guide' },
    { question: 'On a WAC 1:1,000,000 scale, 6.5 cm measured on the chart equals what ground distance?', options: ['A. 35 nm', 'B. 65 nm', 'C. 45 nm', 'D. 21 nm'], correct: 0, explanation: '1:1,000,000 — 1 cm = 10 km. 6.5 cm = 65 km. Convert to nm: 65 / 1.852 = 35.1 nm ≈ 35 nm.', reference: 'CASA CNAV Syllabus / Chart Reading' },
    { question: 'What is the difference between variation and deviation?', options: ['A. Variation is aircraft-specific; deviation is geographic', 'B. Variation is the angular difference between true and magnetic north; deviation is the compass error caused by the aircraft own magnetic fields', 'C. They describe the same error', 'D. Deviation converts true to magnetic; variation converts magnetic to compass'], correct: 1, explanation: 'Variation (declination) is the geographic angle between true and magnetic north — varies by location and changes slowly over time. Deviation is the compass error caused by the aircraft own electrical systems and ferrous metals — varies with aircraft heading and is recorded on the deviation card.', reference: 'CASA CNAV Syllabus / Navigation Study Guide' },
    { question: 'What does a VOR radial represent?', options: ['A. Distance from the VOR station', 'B. A magnetic bearing FROM the VOR station — e.g. on the 090 radial means the aircraft is due east of the station', 'C. A magnetic bearing TO the VOR station', 'D. VOR radials only work with DME'], correct: 1, explanation: 'A VOR radial is a magnetic bearing FROM the station (QDR). On the 090 radial = aircraft is east of the station. Two VOR radials from different stations intersect for a position fix. The CDI needle indicates whether you are left or right of the selected radial.', reference: 'CASA CNAV Syllabus / Radio Navigation Study Guide' },
    { question: 'An aircraft is at the halfway point of a 200 nm flight and is 10 nm left of track. What heading change is required to track directly to destination?', options: ['A. 3 degrees right', 'B. 6 degrees right', 'C. 12 degrees right', 'D. 9 degrees right'], correct: 2, explanation: 'Halfway = 100 nm flown. Track error = (10/100) x 60 = 6 degrees. Closing angle to destination (100 nm remaining) = (10/100) x 60 = 6 degrees. Total correction = 6 + 6 = 12 degrees RIGHT.', reference: 'CASA CNAV Syllabus / 1-in-60 Rule' },
    { question: 'What information does the ERSA contain?', options: ['A. Weather forecasts for en-route flight', 'B. Detailed aerodrome information — frequencies, runways, lighting, fuel, facilities, circuit direction, and local procedures for all Australian aerodromes', 'C. Only IFR approach procedures', 'D. A substitute for aeronautical charts'], correct: 1, explanation: 'The ERSA (En Route Supplement Australia) contains detailed aerodrome information including CTAF/tower frequencies, runways, lighting, fuel types and hours, customs, facilities, circuit direction, and local procedures. An essential pre-flight planning document.', reference: 'CASA CNAV Syllabus / ERSA Introduction' },
    { question: 'What is the Transition Altitude in Australia?', options: ['A. The altitude at which crews switch from QNH to 1013 hPa', 'B. The altitude at which ATC hands off to the next sector', 'C. The height above which terrain separation is guaranteed', 'D. The altitude at which GPWS activates'], correct: 0, explanation: 'The Transition Altitude is the altitude at or below which QNH is used for vertical reference. Above the Transition Layer, aircraft use flight levels referenced to 1013.25 hPa. In Australia the transition altitude is typically 10,000 ft AMSL but varies — check AIP ENR 1.7 for specific areas.', reference: 'AIP ENR 1.7 / CASA CNAV Syllabus' },
  ],

  'Operations Performance Planning': [
    { question: 'Minimum fuel for VFR day Part 91: trip 2h 15min, burn 42 L/hr?', options: ['A. 94.5 litres', 'B. 126 litres', 'C. 78 litres', 'D. 110 litres'], correct: 1, explanation: 'Trip fuel = 42 x 2.25 = 94.5 L. Reserve (45 min) = 42 x 0.75 = 31.5 L. Total = 126 L. Under Part 91 VFR day piston under 5700 kg: trip fuel + 45 min reserve.', reference: 'CASR Part 91 MOS Chapter 19 / CAO 20.9' },
    { question: 'What is Zero Fuel Weight (ZFW) and Maximum Zero Fuel Weight (MZFW)?', options: ['A. ZFW is aircraft weight with minimum fuel; MZFW is maximum empty weight', 'B. ZFW is total weight minus usable fuel; MZFW is the maximum structural weight without wing fuel providing bending relief — exceeding MZFW can cause structural damage', 'C. ZFW equals BEW plus payload; MZFW is set by performance', 'D. They are the same thing'], correct: 1, explanation: 'ZFW is total aircraft weight excluding usable fuel. MZFW is the maximum weight without usable fuel — set by the structural limit at the wing root where fuel in the wings provides bending relief. Exceeding MZFW is illegal even if MTOW is not exceeded.', reference: 'CASA CFPA Syllabus / Mass and Balance Study Guide' },
    { question: 'Aircraft: BEW 820 kg, MTOW 1350 kg, fuel 125 kg, pilot 80 kg. Maximum passengers and baggage?', options: ['A. 325 kg', 'B. 405 kg', 'C. 530 kg', 'D. 280 kg'], correct: 0, explanation: 'Max payload = MTOW - BEW - Fuel - Pilot = 1350 - 820 - 125 - 80 = 325 kg.', reference: 'CASA CFPA Syllabus / Mass and Balance Study Guide' },
    { question: 'What is ramp weight and how does it differ from takeoff weight?', options: ['A. They are identical', 'B. Ramp weight is total weight at engine start including taxi fuel; takeoff weight is ramp weight minus fuel burned during taxi — MTOW applies at brake release, not engine start', 'C. Ramp weight includes the ramp crew weight', 'D. Ramp weight is calculated after landing'], correct: 1, explanation: 'Ramp weight (ramp mass) includes all fuel at engine start. Takeoff weight is ramp weight minus taxi fuel consumed. MTOW applies at the start of the takeoff roll (brake release), not at engine start. A common weak area in CFPA.', reference: 'CASA CFPA Syllabus / Mass and Balance Study Guide' },
    { question: 'What is the effect of a headwind on takeoff distance?', options: ['A. Headwind increases TODR', 'B. Headwind decreases TODR — 10% of liftoff speed in headwind reduces TODR by approximately 19%', 'C. Wind has no effect on TODR', 'D. Headwind increases TODR by the wind speed percentage'], correct: 1, explanation: 'A headwind decreases TODR because the aircraft already has airspeed at the start of the roll. As a rule, 10% of liftoff speed as headwind reduces TODR by approximately 19%. The opposite applies for tailwind — increases TODR significantly.', reference: 'CASA CFPA Syllabus / Performance Study Guide' },
    { question: 'What is the purpose of MAC in mass and balance?', options: ['A. MAC is used to calculate wing area', 'B. MAC is a reference chord length used to express CG position as a percentage — ensures a consistent reference regardless of aircraft size', 'C. MAC is the maximum allowed chord', 'D. MAC is only used on jet aircraft'], correct: 1, explanation: 'The Mean Aerodynamic Chord is used to express CG position as a %MAC. A CG at 25%MAC means the CG is 25% of the MAC length from its leading edge. %MAC is consistent across different aircraft sizes and is used in AFMs. A common weak area in CFPA.', reference: 'CASA CFPA Syllabus / Mass and Balance Study Guide' },
    { question: 'What factors increase TODR beyond POH standard distance?', options: ['A. Headwind, upslope, low density altitude, dry sealed runway', 'B. Tailwind, upslope, high density altitude, grass runway, high gross weight', 'C. High gross weight and flap setting only', 'D. TODR is fixed regardless of conditions'], correct: 1, explanation: 'TODR increases with: tailwind, upslope runway, high density altitude (hot/high/humid), grass or contaminated runway, and high gross weight. All applicable corrections from the workbook must be applied. A common weak area in CFPA.', reference: 'CASA CFPA Syllabus / RPL PPL CPL Workbook' },
    { question: 'What is the Part 91 fuel reserve for a VFR night flight (piston under 5700 kg)?', options: ['A. 1 hour reserve', 'B. 45 minutes at cruise power — same as VFR day under Part 91', 'C. 30 minutes reserve', 'D. Alternate plus 45 minutes'], correct: 1, explanation: 'Under CASR Part 91 MOS Chapter 19 Table 19.02, VFR night for piston aircraft under 5700 kg requires trip fuel plus 45 minutes reserve at cruise — the same requirement as VFR day.', reference: 'CASR Part 91 MOS Chapter 19 Table 19.02' },
    { question: 'What is the consequence of operating aft of the CG limit?', options: ['A. Reduced elevator effectiveness and higher stall speed only', 'B. Reduced or negative longitudinal stability — the aircraft may pitch up uncontrollably and enter an irrecoverable stall', 'C. CG limits only affect passenger comfort', 'D. Aft CG only affects fuel consumption'], correct: 1, explanation: 'Aft of limits is the most dangerous CG condition. With neutral or negative stability, the aircraft may pitch up uncontrollably and enter an irrecoverable stall. Forward CG reduces elevator effectiveness; aft CG removes stability entirely. Both limits must always be respected.', reference: 'CASA CFPA Syllabus / Mass and Balance Study Guide' },
    { question: 'What is Va and why does it decrease with reducing aircraft weight?', options: ['A. Va increases as weight decreases', 'B. Va decreases as weight decreases — lighter aircraft stall at lower speeds, so the aircraft stalls (safely) before reaching the structural limit at a lower speed', 'C. Va remains constant regardless of weight', 'D. Va only changes with altitude'], correct: 1, explanation: 'Va is the maximum speed for full control deflection without structural overstress. At reduced weight, stall speed is lower so Va is lower — the aircraft stalls before reaching the limit load factor at a lower airspeed. Always check AFM for Va at actual aircraft weight.', reference: 'CASA CFPA Syllabus / Aircraft Flight Manual' },
  ],

  'Flight Rules and Air Law': [
    { question: 'VFR minima in Class G airspace at or below 3000 ft AMSL by day?', options: ['A. 5 km visibility, 1000 ft above/below, 1 nm horizontally', 'B. 1500 m flight visibility, clear of cloud', 'C. 5000 m, 500 ft below, 1000 ft above, 600 m horizontal', 'D. 8 km visibility, CAVOK only'], correct: 1, explanation: 'In Class G airspace at or below 3000 ft AMSL or 1000 ft AGL by day: minimum 1500 m flight visibility and clear of cloud. Above these levels the minima increase to 5 km with defined cloud clearances.', reference: 'CASR Part 91 MOS / AIP ENR 1.2' },
    { question: 'The CLWA exam requires an 80% pass mark. What pass mark applies to most other CPL exams?', options: ['A. 75%', 'B. 70%', 'C. 65%', 'D. 80% for all CPL exams'], correct: 1, explanation: 'Most CPL exams require 70% to pass. CLWA (Air Law) requires 80% — the highest pass mark for CPL subjects, reflecting the critical importance of regulatory knowledge for safe legal operations.', reference: 'CASA CLWA Syllabus / CASR' },
    { question: 'When two aircraft converge at the same altitude, which gives way?', options: ['A. Slower aircraft gives way to faster', 'B. Aircraft with the other on its LEFT must give way — the aircraft on the right has right of way', 'C. Higher aircraft gives way to lower', 'D. IFR gives way to VFR'], correct: 1, explanation: 'Under CASR Part 91 rules of the air: when converging at approximately the same altitude, the aircraft with the other on its LEFT must give way. The aircraft on the RIGHT has right of way. A common weak area in CLWA.', reference: 'CASR Part 91.080 / AIP ENR 1.1' },
    { question: 'VFR cloud clearance above 3000 ft AMSL in Class G airspace?', options: ['A. 1500 m visibility, clear of cloud', 'B. 5 km visibility, 1000 ft above, 1000 ft below, 1 nm horizontally', 'C. 8 km, CAVOK only', 'D. 3 km, 500 ft vertical, 600 m horizontal'], correct: 1, explanation: 'Above 3000 ft AMSL (or 1000 ft AGL) in Class G: 5 km visibility, 1000 ft above cloud, 1000 ft below cloud, 1 nm horizontally from cloud. These are more stringent than the low-level minima. A common weak area in CLWA.', reference: 'CASR Part 91 MOS / AIP ENR 1.2' },
    { question: 'What are the requirements for operating in an MBZ (Mandatory Broadcast Zone)?', options: ['A. No radio required', 'B. Mandatory position reports on the published MBZ frequency at specified points — inbound, joining, taking the runway, airborne, and clear of the runway', 'C. ATC clearance required before entry', 'D. MBZs only apply to IFR aircraft'], correct: 1, explanation: 'In an MBZ, pilots self-coordinate by making mandatory broadcasts on the published frequency. Required calls include: inbound (with intentions), joining the circuit, taking the runway, airborne, and clear of the runway area. No ATC service is provided.', reference: 'AIP ENR 1.1 / CASR Part 91' },
    { question: 'What pilot maintenance tasks are permitted under CASR Part 43 Schedule 8?', options: ['A. No maintenance tasks are permitted', 'B. Certain simple tasks listed in Schedule 8 — replacing consumables and minor adjustments specified in the maintenance manual', 'C. Any maintenance task with a CPL', 'D. Pilot maintenance only permitted under LAME supervision'], correct: 1, explanation: 'CASR Part 43 Schedule 8 specifies tasks that a licensed pilot may perform — typically replacing consumables (oil, fuel, filters within limits), checking/topping fluids, replacing globes, and simple adjustments specified in the AFM. Pilots cannot perform line maintenance beyond Schedule 8. A common weak area in CLWA.', reference: 'CASR Part 43 Schedule 8' },
    { question: 'Right of way order between different aircraft categories?', options: ['A. Faster aircraft always have priority', 'B. Less maneuverable aircraft have priority: balloons, gliders, airships, aircraft towing loads, then powered aircraft. Aircraft in distress have priority over all', 'C. Larger aircraft always have priority', 'D. IFR always has priority over VFR'], correct: 1, explanation: 'Right of way order (most priority first): aircraft in distress, balloons, gliders, airships, aircraft towing/carrying slung loads, powered aircraft. The principle is that less maneuverable aircraft have right of way. All pilots share collision avoidance responsibility.', reference: 'CASR Part 91 / AIP ENR 1.1' },
    { question: 'Requirements to act as PIC under CASR Part 61?', options: ['A. Hold any grade of pilot licence and a current medical', 'B. Hold appropriate licence for the aircraft category and class, hold a current medical of the required class, and comply with recency requirements (3 takeoffs and landings in 90 days for day VFR)', 'C. CPL required for all aircraft operations', 'D. Licence requirements only apply to commercial operations'], correct: 1, explanation: 'CASR Part 61 PIC requirements: appropriate pilot licence for the category/class, current medical certificate, and recency (typically 3 takeoffs and landings in preceding 90 days for day VFR). Additional requirements apply for night, IFR, and specific operations.', reference: 'CASR Part 61 / CASA CLWA Syllabus' },
    { question: 'What is a controlled aerodrome and what communication requirements apply?', options: ['A. Any aerodrome with a sealed runway', 'B. An aerodrome with an operating control tower — two-way radio must be established and ATC clearances obtained before all movements', 'C. Any aerodrome listed in ERSA', 'D. An aerodrome in Class C airspace only'], correct: 1, explanation: 'A controlled aerodrome has an operating ATC tower (Class C, D, or E). Requirements: establish two-way radio contact before any movement, obtain taxi/takeoff/landing clearances, comply with all ATC instructions, and read back clearances as required.', reference: 'CASR Part 91 / AIP ENR 1.1' },
    { question: 'What is a SARTIME and when is it required?', options: ['A. Mandatory for all VFR flights', 'B. A time lodged with NAIPS or a responsible person after which SAR action begins if the aircraft has not arrived or reported', 'C. Only required for IFR flights', 'D. Only required for overwater flights'], correct: 1, explanation: 'A SARTIME is lodged with NAIPS or a responsible person. If the aircraft has not reported by the nominated time, SAR action begins. Mandatory for remote area flights, overwater operations, and other specified operations. Good airmanship to use for all cross-country flights.', reference: 'CASR Part 91 / AIP ENR 1.10' },
  ],

  // ─── ATPL ───────────────────────────────────────────────────
  'Human Factors Advanced': [
    { question: 'In the TEM framework, what is the difference between an organisational threat and an environmental threat?', options: ['A. They are the same type of threat', 'B. Organisational threats come from within the operator (scheduling, procedures, culture, training); environmental threats are external to the operator (weather, terrain, traffic, contaminated runway)', 'C. Environmental threats are more dangerous than organisational threats', 'D. Organisational threats only affect maintenance personnel'], correct: 1, explanation: 'TEM categorises threats: Organisational (company scheduling, procedures, inadequate training, safety culture), Environmental (weather, terrain, other traffic, contaminated runway, ATC errors), and Threat-in-context (unexpected events during flight). Both categories must be identified and managed. A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / ICAO TEM Framework Doc 9683' },
    { question: 'What is an Undesired Aircraft State (UAS) and give an example?', options: ['A. Any aircraft system malfunction', 'B. A flight crew-induced aircraft position, speed, attitude, or configuration that reduces safety margins — e.g. unstabilised approach, aircraft below glidepath at MDA, configuration error on departure', 'C. Any deviation from SOPs', 'D. An ATC instruction conflicting with procedures'], correct: 1, explanation: 'A UAS is crew-induced and reduces safety margins. Examples: aircraft below glidepath on approach, exceeding speed limits, wrong flap configuration on departure. A UAS is the third tier of TEM — if not corrected, it can lead to an accident. Key word: crew-induced. A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / ICAO Doc 9683' },
    { question: 'What communication style is most effective for a first officer challenging a captain\'s error?', options: ['A. Passive — suggest diplomatically and defer to the captain', 'B. Assertive — state the observation, state the concern, propose a solution, and seek agreement (PACE or similar structured approach)', 'C. Aggressive — take over the controls immediately', 'D. Passive-aggressive — complete the action under protest'], correct: 1, explanation: 'Assertive communication is the CRM standard for challenging authority. Structure: state what you observe (fact), state your concern, propose an alternative, seek acknowledgement. Neither passive (may not prevent error) nor aggressive (damages team function). A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / CRM Study Guide / AC 119-22' },
    { question: 'What is the difference between a skill-based error and a rule-based error in Reason\'s GEMS model?', options: ['A. Skill-based errors occur at high workload only', 'B. Skill-based errors are slips and lapses in automatic behaviour; rule-based errors are mistakes involving wrong application of a rule or using the wrong rule for a situation', 'C. Rule-based errors are more serious than skill-based errors', 'D. They are identical error types described differently'], correct: 1, explanation: 'Reason\'s GEMS: Skill-based errors (slips/lapses) — errors in automatic/habitual behaviour (pressing wrong button through habit, forgetting a step). Rule-based mistakes — applying wrong rule or misapplying correct rule (using wrong checklist for the situation). Knowledge-based mistakes — errors requiring first-principles reasoning. A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / Reason GEMS model' },
    { question: 'What is channelised attention (fixation) and give an aviation example of its consequences?', options: ['A. The ability to focus exclusively on one task — always beneficial', 'B. Excessive focus on one task or instrument to the exclusion of other critical information — e.g. Eastern Air Lines 401: crew fixed on a faulty gear indicator while the autopilot disengaged and the aircraft descended into the Everglades', 'C. Normal task prioritisation at high workload', 'D. Fixation only affects single-pilot operations'], correct: 1, explanation: 'Channelised attention is one of the most dangerous cognitive traps. The Eastern Air Lines 401 accident (1972) is the classic example: the crew fixated on a faulty gear light while inadvertently disengaging the autopilot, and the aircraft descended unnoticed into the Everglades. 99 fatalities. A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / Human Factors Study Guide / NTSB Report' },
    { question: 'What is the somatogravic illusion and why is it particularly dangerous during a go-around?', options: ['A. A false banking sensation in clouds', 'B. Rapid acceleration causes the otoliths to interpret forward acceleration as nose-up pitch — the pilot may push forward to correct the false nose-high sensation, potentially flying into terrain during a low-level go-around', 'C. A rolling illusion caused by the semicircular canals', 'D. An illusion only affecting helicopter pilots'], correct: 1, explanation: 'The somatogravic illusion occurs during rapid acceleration. During a go-around at night or in IMC, the sudden application of full power creates strong forward acceleration interpreted as nose-up pitch. The pilot may instinctively push forward — at low altitude this is fatal. The antidote is trust instruments absolutely.', reference: 'CASA AHUF Syllabus / Human Factors Study Guide' },
    { question: 'What is the purpose of a pre-flight CRM briefing and what should it cover?', options: ['A. Only to allocate PF and PM duties', 'B. To establish shared mental models, clarify roles, review sector threats, agree on communication norms, and prepare the crew to work effectively as a team', 'C. To review company procedures only', 'D. CRM briefings are only required for long-haul operations'], correct: 1, explanation: 'Pre-flight CRM briefings establish the foundation for effective teamwork. They should cover: crew introductions and relevant experience, role allocation (PF/PM), anticipated threats on the sector (weather, NOTAMs, terrain, traffic), communication expectations, and how the crew will handle abnormal situations.', reference: 'CASA AHUF Syllabus / AC 119-22 CRM Training' },
    { question: 'What is threat trapping and how is it achieved?', options: ['A. Using ATC radar to detect traffic threats', 'B. Proactively identifying and managing threats before they generate errors — through briefings, anticipating known hazards, using standard calls, and cross-checking critical items', 'C. Reporting threats to company safety management', 'D. Simulator training only'], correct: 1, explanation: 'Threat trapping is proactive TEM — identifying and managing threats before they cause errors. Methods: pre-flight threat briefings (ATIS, NOTAMs, terrain, weather), standard calls for verification (gear check, speed check), using checklists at correct times, and cross-checking captain inputs as PM.', reference: 'CASA AHUF Syllabus / ICAO TEM Framework' },
    { question: 'What are the types of human error in aviation and how are they categorised?', options: ['A. Only two types: intentional and unintentional', 'B. Errors are categorised as: slips (wrong action, right intention), lapses (memory failure), and mistakes (wrong intention — rule-based or knowledge-based). Violations are intentional deviations from procedures', 'C. Human errors cannot be categorised — each is unique', 'D. Errors are only categorised as maintenance or flight crew errors'], correct: 1, explanation: 'Error taxonomy: Slips — correct intention but wrong action (selecting wrong autopilot mode). Lapses — correct intention but memory failure (forgetting a checklist item). Mistakes — wrong intention applied (using wrong procedure). Violations — intentional deviation (skipping checklist under time pressure). Each requires different countermeasures. A common weak area in AHUF.', reference: 'CASA AHUF Syllabus / Reason GEMS / Human Factors Study Guide' },
    { question: 'What is the role of the Pilot Monitoring (PM) in a two-crew operation?', options: ['A. The PM is a passive observer', 'B. The PM actively monitors all parameters, cross-checks PF actions, manages communications and checklists, calls deviations, and is prepared to take control — an effective PM is critical to safety', 'C. The PM only handles radio communications', 'D. The PM takes control whenever workload increases'], correct: 1, explanation: 'The PM role is an active safety function. Duties: monitor flight parameters (speed, altitude, attitude), cross-check PF inputs on critical phases, run checklists, manage ATC communication, call deviations (speed, sink rate), and maintain full situational awareness ready to take control if needed. Poor PM performance is implicated in many CRM accidents.', reference: 'CASA AHUF Syllabus / FCTM / CRM principles' },
  ],

  'Aerodynamics Advanced': [
    { question: 'What is a high-speed stall (Mach tuck) and how does it affect swept-wing aircraft?', options: ['A. High-speed stall is the same as a low-speed stall but at higher IAS', 'B. As aircraft approach Mcrit, shock waves form on the wing causing the CP to move aft, creating a nose-down pitching moment (Mach tuck) — if not corrected it can lead to structural failure or loss of control', 'C. High-speed stall only affects jet engines not the airframe', 'D. Mach tuck only occurs above FL500'], correct: 1, explanation: 'As airspeed approaches Mcrit, local airflow over the wing reaches Mach 1, creating shock waves. The shock wave causes flow separation and moves the centre of pressure aft, creating a strong nose-down pitching moment (Mach tuck). This is why VMO/MMO limits exist and why Mach trim compensators are fitted to swept-wing aircraft.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is Dutch roll and how is it managed in swept-wing jet aircraft?', options: ['A. Dutch roll is excessive aileron sensitivity', 'B. Dutch roll is a coupled lateral-directional oscillation (roll and yaw together) common in swept-wing aircraft with high dihedral effect and low directional stability — managed by a yaw damper system', 'C. Dutch roll only occurs at low speed near the stall', 'D. Dutch roll is caused by asymmetric engine thrust'], correct: 1, explanation: 'Dutch roll is an oscillation coupling roll and yaw that can be uncomfortable or uncontrollable. High-aspect-ratio swept wings have strong dihedral effect but often insufficient directional stability (keel effect). Yaw dampers automatically apply small rudder inputs to damp the oscillation. Disconnected yaw damper = Dutch roll tendency. A common weak area in AADA.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is spanwise flow on a swept-wing aircraft and how does it affect stall characteristics?', options: ['A. Spanwise flow improves stall characteristics', 'B. On swept wings, boundary layer air tends to flow spanwise toward the tips — this reduces boundary layer energy at the tips causing tip stall first, which is dangerous as ailerons lose effectiveness before the root stalls (unlike straight wings)', 'C. Spanwise flow only affects induced drag', 'D. Spanwise flow is beneficial as it reduces pressure drag'], correct: 1, explanation: 'On swept wings, the spanwise pressure gradient drives boundary layer flow toward the wingtips. This thickens and slows the boundary layer at the tips, causing tip stall first. Tip stall is dangerous — ailerons (located near the tips) become ineffective just as the stall occurs. Cures: wing fences, leading edge slots, washout, or leading edge extensions.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is the effect of compressibility on the pitot-static system at high Mach numbers?', options: ['A. Compressibility has no effect on pitot-static readings', 'B. At high Mach numbers, the ram effect compresses the air in the pitot tube more than at low speeds — indicated airspeed reads higher than calibrated airspeed. A compressibility correction is applied to convert CAS to equivalent airspeed (EAS)', 'C. Compressibility causes the airspeed indicator to read lower than actual', 'D. Compressibility corrections are only required above FL450'], correct: 1, explanation: 'At high Mach numbers, air compresses in front of the pitot tube beyond what is assumed in the IAS calibration. This makes IAS (and CAS) read higher than actual EAS. Compressibility corrections reduce CAS to EAS. At low altitude and speed, CAS ≈ EAS. The correction becomes significant above approximately Mach 0.4.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is load alleviation and how does it affect turbulence penetration speed (Vra)?', options: ['A. Load alleviation is only used for takeoff and landing', 'B. Load alleviation systems (such as spoilers that automatically deploy symmetrically) reduce wing bending loads in turbulence — Vra (rough air speed) is the recommended turbulence penetration speed that balances stall margin and structural protection', 'C. Vra is always the same as Vmo', 'D. Load alleviation is not relevant to commercial aircraft'], correct: 1, explanation: 'Vra (turbulence penetration speed, also called rough air speed) is selected to provide adequate stall margin while keeping gust loads within structural limits. It is typically well below Vmo. Automatic load alleviation systems (active spoilers, control surface limiters) help protect the structure from gust loads in turbulence.', reference: 'CASA AADA Syllabus / Aircraft Flight Manual / Advanced Aerodynamics' },
    { question: 'What is the significance of the buffet onset boundary on a jet aircraft cruise chart?', options: ['A. The buffet boundary only applies at low altitude', 'B. The buffet onset boundary shows combinations of altitude and Mach number/speed where aerodynamic buffet begins — staying within the boundary ensures adequate stall and high-speed buffet margins during cruise manoeuvres', 'C. Buffet boundary charts are only used for emergency procedures', 'D. Buffet onset is not related to altitude'], correct: 1, explanation: 'The buffet onset boundary chart shows the flight envelope where manoeuvre margins exist. At high altitude and high weight, the low-speed (stall) buffet and high-speed (compressibility) buffet boundaries converge — reducing the usable speed range (Coffin corner). At cruise altitude, adequate margins must be maintained for manoeuvres such as turns.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics / Aircraft Operations Manual' },
    { question: 'What is the purpose of leading edge devices (slats/Krueger flaps) and how do they affect the stall?', options: ['A. Leading edge devices only improve high-speed performance', 'B. Leading edge devices increase the maximum lift coefficient and critical angle of attack by improving airflow attachment at high AoA — they significantly reduce stall speed and improve low-speed handling', 'C. Leading edge devices increase stall speed', 'D. Leading edge devices only affect drag not lift'], correct: 1, explanation: 'Leading edge slats create a slot between the slat and the main wing element, allowing high-energy air to re-energise the upper surface boundary layer. This allows higher angles of attack before separation, increasing maximum lift coefficient and reducing stall speed by up to 30%. They are essential for jet aircraft approach speeds.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is aeroelastic flutter and how is it prevented?', options: ['A. Flutter is minor vibration that is always controllable', 'B. Flutter is a self-sustaining oscillation coupling aerodynamic forces with structural elastic deformation — it can rapidly increase in amplitude to structural failure. Prevented by mass balancing control surfaces and maintaining V below Vne/Vmo', 'C. Flutter only affects propeller-driven aircraft', 'D. Flutter is prevented by increasing structural weight'], correct: 1, explanation: 'Flutter occurs when aerodynamic forces couple with structural elasticity in a positive feedback loop. Above a critical speed, the oscillations grow exponentially and can cause structural failure in seconds. Prevention: mass balancing control surfaces (moving CG forward of the hinge line), operating below Vne/Vmo, and structural design margins.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics Study Guide' },
    { question: 'What is propulsive efficiency and how does it change with airspeed for a jet engine?', options: ['A. Propulsive efficiency is constant regardless of airspeed', 'B. Propulsive efficiency = useful work / total energy. For a jet, it increases with airspeed as the ratio of flight speed to jet velocity improves — at low speed most jet kinetic energy is wasted; at high speed the engine is most efficient', 'C. Propulsive efficiency decreases with airspeed', 'D. Propulsive efficiency is only relevant for propeller aircraft'], correct: 1, explanation: 'Propulsive efficiency for a jet engine increases with aircraft speed. At low speed, the jet exhaust velocity is much higher than flight speed — most energy is wasted in the jet wake. At higher flight speeds, the energy conversion becomes more efficient. This is why jet aircraft are most efficient at high altitude and high speed.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics / Jet Propulsion' },
    { question: 'What is the effect of icing on lift and drag and why is it particularly dangerous at low speed?', options: ['A. Icing only increases weight with no aerodynamic effect', 'B. Ice contamination on the wing reduces maximum lift coefficient, increases stall speed, and dramatically increases drag — even small amounts of contamination (frost) can increase stall speed by 30% or more, making icing particularly dangerous on approach', 'C. Icing only affects engines, not aerodynamics', 'D. Icing reduces drag by smoothing the wing surface'], correct: 1, explanation: 'Ice contamination disrupts smooth airflow, reducing lift coefficient and increasing stall speed and drag. Even a thin layer of frost can increase stall speed by 30%+ and reduce maximum lift by 40%. At approach speeds (low margin above stall), this is catastrophic. No aircraft may take off with ice, snow, or frost on any lift-producing surface.', reference: 'CASA AADA Syllabus / Advanced Aerodynamics / AIP ENR' },
  ],

  'Aircraft General Advanced': [
    { question: 'What is a maintenance release and what must it state for the aircraft to be airworthy?', options: ['A. A maintenance release is an optional document', 'B. A maintenance release certifies the aircraft is airworthy and may be flown. It must state the aircraft is serviceable (or list deferred defects per MEL), be signed by an authorised certifying staff member, and not be expired by time, cycles, or calendar limits', 'C. The PIC can sign the maintenance release', 'D. A maintenance release is only required after major maintenance'], correct: 1, explanation: 'A maintenance release (MR) is a legal certification of airworthiness. It must: be signed by authorised certifying staff (LAME/AME), state the aircraft is airworthy (or list MEL deferred items), and be valid (not expired by any limit). Flying without a valid MR is illegal under CASR Part 42. A common weak area in AASY.', reference: 'CASR Part 42 / Part 121 / CASA AASY Syllabus' },
    { question: 'What is the function of a Full Authority Digital Engine Control (FADEC) system?', options: ['A. FADEC only controls fuel flow', 'B. FADEC is an electronic system that fully controls all aspects of engine operation (fuel flow, variable geometry, start sequencing, protection limits) — it prevents engine exceedances, optimises performance, and simplifies pilot workload by removing manual engine management', 'C. FADEC requires constant pilot input to function', 'D. FADEC is only used on military aircraft'], correct: 1, explanation: 'FADEC replaces manual engine controls with a digital system that manages all engine parameters automatically. Benefits: prevents overtemperature, overspeed, and compressor stall; optimises fuel burn; simplifies cockpit; provides engine health monitoring. Limitation: FADEC failure requires reversion to mechanical backup or results in reduced performance.', reference: 'CASA AASY Syllabus / Advanced Aircraft Systems' },
    { question: 'What is an Emergency Airworthiness Directive (EAD) and what action must an operator take?', options: ['A. EADs are optional safety recommendations', 'B. An EAD is mandatory action issued by CASA (or a foreign authority with Australian recognition) for an urgent airworthiness issue — it must be complied with within the specified time frame before further flight is permitted', 'C. EADs apply only to aircraft over 5700 kg', 'D. EADs can be deferred indefinitely under the MEL'], correct: 1, explanation: 'Emergency Airworthiness Directives are mandatory and legally binding. They address urgent safety issues requiring immediate action (sometimes before next flight). An operator or owner must comply within the specified timeframe. Non-compliance makes the aircraft unairworthy and the flight illegal. Regular ADs have longer compliance times.', reference: 'CASR Part 39 / CASA AASY Syllabus' },
    { question: 'What is the purpose of a Cabin Pressure Controller and what happens if it fails?', options: ['A. The pressure controller only controls temperature', 'B. The pressure controller maintains the aircraft cabin at a safe pressure altitude by regulating outflow valves — failure to pressurize requires descent to an altitude where supplemental oxygen is not required, typically 10,000 ft or below', 'C. Pressurisation failure automatically triggers an emergency descent', 'D. The pressure controller is a backup to the outflow valve only'], correct: 1, explanation: 'The pressurisation controller regulates outflow valves to maintain a cabin altitude typically 6,000-8,000 ft at cruise. A failed controller may cause cabin altitude to rise — the crew must respond by donning oxygen masks, declaring emergency, and descending to an altitude where supplemental oxygen is not required (typically 10,000 ft). Time of useful consciousness decreases rapidly above 25,000 ft.', reference: 'CASA AASY Syllabus / Advanced Aircraft Systems' },
    { question: 'What is the difference between an automatic and a manual pressurisation system?', options: ['A. They provide identical functionality', 'B. Automatic pressurisation uses a controller that automatically maintains the selected cabin altitude by regulating outflow valves; manual mode requires the crew to manually position the outflow valve to achieve and maintain desired cabin pressure', 'C. Manual pressurisation is not permitted in commercial operations', 'D. Automatic pressurisation is only used on large aircraft'], correct: 1, explanation: 'Automatic pressurisation: controller maintains cabin altitude automatically with crew setting desired cabin altitude. Manual mode: crew manually controls outflow valve position — more workload intensive but essential backup if automatic system fails. Crews must be proficient in manual pressurisation. A common weak area in AASY.', reference: 'CASA AASY Syllabus / Advanced Aircraft Systems' },
    { question: 'What is a Central Maintenance Computer (CMC) and what information does it provide?', options: ['A. CMC controls all aircraft systems automatically', 'B. The CMC collects fault data from aircraft systems during flight and on ground, providing maintenance crews with fault codes, LRU (Line Replaceable Unit) identification, and fault history to facilitate efficient troubleshooting and rectification', 'C. CMC is only used for weight and balance calculations', 'D. Pilots access CMC data directly from the cockpit during flight to manage faults'], correct: 1, explanation: 'The CMC (or equivalent ACARS/BITE systems) monitors aircraft systems and records faults as they occur. Maintenance crews access CMC data post-flight to identify failed LRUs and plan maintenance. Some systems can transmit fault data via ACARS in real-time so maintenance is ready on arrival. Pilots see synthesised fault messages on ECAM/EICAS.', reference: 'CASA AASY Syllabus / Advanced Aircraft Systems' },
    { question: 'What is ETOPS and what are the key approval requirements?', options: ['A. ETOPS only applies to three-engine aircraft', 'B. ETOPS (Extended Range Twin Operations) allows twin-engine aircraft to fly routes more than 60 minutes from a diversion airport — requires CASA operator approval, specific aircraft reliability standards, crew training, maintenance requirements, and route-specific planning', 'C. ETOPS approval is automatically granted with an ATPL', 'D. ETOPS only applies above FL400'], correct: 1, explanation: 'ETOPS allows twins to fly routes previously restricted to triplanes/quads. ETOPS requires: CASA operator approval (e.g. 120/180/240 min), aircraft with demonstrated engine reliability (IFSD rate), approved maintenance programme, crew training and procedures, route-specific weather and alternate planning, and fuel for single-engine diversion. A common weak area in AASY.', reference: 'CASR Part 121 / CASA AASY Syllabus' },
    { question: 'What is the purpose of engine trend monitoring (ETM)?', options: ['A. ETM monitors only fuel consumption', 'B. ETM compares engine parameter readings (EGT, fuel flow, N1, N2, oil pressure/temperature) against established baselines to detect gradual performance deterioration before it becomes a safety issue or causes in-flight engine failure', 'C. ETM is used only during engine start', 'D. ETM replaces the engine maintenance schedule'], correct: 1, explanation: 'Engine trend monitoring tracks engine health over time by recording parameters at consistent conditions (altitude, speed, thrust setting). Gradual increases in EGT trend or fuel flow trend, or decreases in N1 for the same fuel flow, indicate performance degradation. Early detection allows planned maintenance rather than reactive maintenance after failure.', reference: 'CASA AASY Syllabus / Advanced Aircraft Systems / ICAO Engine Health Monitoring' },
    { question: 'What is a Structural Repair Manual (SRM) and when is it used?', options: ['A. The SRM is a document for passengers to review', 'B. The SRM is an approved document providing instructions for inspecting, classifying, and repairing structural damage to the aircraft — any structural repair must comply with the SRM or receive specific engineering authorisation', 'C. The SRM only applies to cosmetic repairs', 'D. The SRM is only used by aircraft manufacturers, not operators'], correct: 1, explanation: 'The SRM (issued by the aircraft manufacturer) provides approved repair methods for structural damage. Any structural repair that exceeds SRM limits requires engineering order/DAR approval. Performing unauthorised structural repairs makes the aircraft unairworthy. A common weak area in AASY.', reference: 'CASR Part 42 / CASA AASY Syllabus' },
    { question: 'What is the function of a hydraulic power transfer unit (PTU)?', options: ['A. PTU transfers hydraulic fluid between systems', 'B. A PTU transfers hydraulic power (not fluid) between systems using a motor-pump combination — if one hydraulic system loses pressure, the PTU can use an adjacent system\'s pressure to power the affected system\'s pump, maintaining hydraulic power', 'C. PTU is only used during engine start', 'D. PTU is an emergency-only system activated by the crew'], correct: 1, explanation: 'The Power Transfer Unit uses a hydraulic motor (powered by one system) driving a pump (pressurising another system) — no fluid is exchanged between systems, only power. The PTU activates automatically when a pressure differential is detected between systems. The characteristic "barking" noise heard during pushback (with one engine running) is the PTU cycling.', reference: 'CASA AASY Syllabus / Advanced Aircraft Hydraulic Systems' },
  ],

  'Meteorology Advanced': [
    { question: 'What is the jet stream and what are its implications for ATPL-level flight operations?', options: ['A. The jet stream is only relevant for flights above FL500', 'B. The jet stream is a narrow band of high-speed winds at the tropopause — ATPL crews must plan routes to exploit tailwind components, avoid significant headwinds, and manage CAT risk on the poleward flank, where horizontal wind shear is greatest', 'C. Jet streams only flow east-west and are easily avoided', 'D. Jet stream effects are negligible for flights under 6 hours'], correct: 1, explanation: 'For ATPL operations, jet stream planning is critical: tailwind assistance can save significant fuel and time; headwinds can cause fuel emergencies on long-range flights; CAT is most prevalent on the poleward (cold) side where isotachs are tightly packed. Jet stream position shifts seasonally and is depicted on significant weather charts and upper-level forecasts. A common weak area in AMET.', reference: 'CASA AMET Syllabus / Meteorology Study Guide' },
    { question: 'What is clear air turbulence (CAT) and how does a crew identify, avoid, and respond to it?', options: ['A. CAT is visible turbulence that can be avoided by looking out the window', 'B. CAT is turbulence in cloudless air with no visual warning — identified using upper-level significant weather charts, PIREPs, and isotach analysis. Avoidance: route away from jet stream flanks. Response: reduce to turbulence penetration speed (Vra) and maintain altitude if possible', 'C. CAT only occurs above FL450', 'D. Weather radar reliably detects CAT'], correct: 1, explanation: 'CAT gives no visual warning and is not detected by weather radar (no moisture). Information sources: SIGMETs, upper-level significant weather charts (tightly packed isotachs), PIREPs (most reliable), and turbulence forecasts. Penetration: reduce to Vra, fasten seatbelts, and consider altitude change. The poleward jet flank and mountain wave regions are highest-risk areas. A common weak area in AMET.', reference: 'CASA AMET Syllabus / Meteorology Study Guide' },
    { question: 'What hazards do thunderstorms present to a jet aircraft at cruise altitude?', options: ['A. Thunderstorms only affect aircraft below 20,000 ft', 'B. Severe/extreme turbulence (including in the anvil), severe icing above the freezing level, large hail ejected ahead of and above the CB top, lightning (can damage avionics), St. Elmo\'s fire, and volcanic ash from embedded convection', 'C. Only the heavy rain poses a risk', 'D. Thunderstorms are only dangerous during approach and landing'], correct: 1, explanation: 'CB hazards at cruise altitude: turbulence extends well beyond the visible cloud (20 nm separation minimum recommended by ICAO), anvil contains severe turbulence and icing, large hail can be found 20+ nm ahead of visible CBs and above the visible top, lightning affects avionics, and embedded CBs in stratiform cloud provide no visual warning on radar. A common weak area in AMET.', reference: 'CASA AMET Syllabus / Meteorology Study Guide' },
    { question: 'What is a TAF3 (Three-scenario forecast) and how does it differ from a standard TAF?', options: ['A. TAF3 is a 3-hour forecast only', 'B. TAF3 provides three probability-based scenarios (most likely, better, worse) for major aerodromes — it gives operators a complete picture of forecast uncertainty for dispatch decisions, unlike a standard TAF which shows only the most likely conditions', 'C. TAF3 is identical to a standard TAF but issued three times daily', 'D. TAF3 applies only to military aerodromes'], correct: 1, explanation: 'TAF3 is a probabilistic forecast issued for major Australian aerodromes. Three scenarios: Most likely conditions, a better-than-expected scenario, and a worse-than-expected scenario — each with associated probability and timing. This gives airlines better information for dispatch decisions, fuel planning, and alternate selection compared to a deterministic TAF. A common weak area in AMET.', reference: 'CASA AMET Syllabus / BOM TAF3 Guide / AIP GEN 3.5' },
    { question: 'What are the synoptic-scale weather systems responsible for significant weather in Australian airspace?', options: ['A. Only tropical cyclones affect Australian aviation', 'B. East coast lows, cut-off lows, cold fronts with embedded CBs, northwest cloudbands, tropical cyclones (north of 26°S, Nov-Apr), and upper troughs — each has characteristic hazards for aviation', 'C. Australian weather is too stable for significant synoptic systems', 'D. Only cold fronts are significant for aviation in Australia'], correct: 1, explanation: 'Key Australian aviation weather systems: East coast lows (intense cyclogenesis off NSW coast — severe conditions); cut-off lows (upper-level troughs that become isolated — persistent bad weather); northwest cloudbands (vast cloud structures bringing tropical moisture south); cold fronts (southern Australia — embedded CBs, wind shear); tropical cyclones (north, summer — extreme conditions). A common weak area in AMET.', reference: 'CASA AMET Syllabus / Meteorology Study Guide / BOM' },
    { question: 'What is the difference between a SIGMET and an AIRMET?', options: ['A. They are identical products from different agencies', 'B. SIGMET warns of phenomena hazardous to ALL aircraft (severe turbulence, severe icing, volcanic ash, tropical cyclone, widespread sandstorm); AIRMET warns of phenomena hazardous specifically to low-level or light aircraft operations', 'C. SIGMET is for IFR aircraft; AIRMET for VFR', 'D. AIRMET covers a larger area than SIGMET'], correct: 1, explanation: 'SIGMETs cover phenomena dangerous to all aircraft regardless of size: severe/extreme turbulence, severe icing, volcanic ash cloud, tropical cyclone, widespread dust/sandstorm. AIRMETs cover phenomena hazardous primarily to low-level operations: moderate turbulence, moderate icing, mountain wave, widespread reduced visibility. Both are available via NAIPS.', reference: 'CASA AMET Syllabus / AIP MET 3.2-3.3' },
    { question: 'What is orographic turbulence (mountain wave) and at what altitudes can it affect jet operations?', options: ['A. Mountain waves only exist below 10,000 ft', 'B. Mountain waves form when stable air crosses elevated terrain — waves can extend to FL500 or above with severe/extreme turbulence in the rotor zone below wave crests. Lenticular clouds mark the crests; rotor turbulence occurs below, even far downwind', 'C. Mountain waves only produce mild turbulence', 'D. Mountain waves only affect light aircraft'], correct: 1, explanation: 'Mountain waves (standing or lee waves) can extend from the surface to extreme altitudes. The rotor zone (below wave crests, near the surface) contains the most severe turbulence. Wave crests are marked by lenticular clouds. At jet cruise altitudes, mountain wave CAT can occur with no cloud (dry atmosphere). Severe mountain wave has caused structural failures of jet aircraft.', reference: 'CASA AMET Syllabus / Meteorology Study Guide' },
    { question: 'How does the tropopause affect thunderstorm development and jet operations?', options: ['A. The tropopause has no effect on thunderstorm development', 'B. The tropopause acts as a lid on convection — anvils spread horizontally at the tropopause level. For jet operations, flying at or near the tropopause means potential for embedded CB anvil turbulence and icing, especially in tropical regions where CB tops can penetrate the lower stratosphere', 'C. The tropopause enhances thunderstorm development', 'D. The tropopause only affects operations above FL450'], correct: 1, explanation: 'The tropopause is the upper limit of tropospheric convection (inversion caps rising air). CB anvils spread horizontally at the tropopause. In the tropics, CBs can overshoot the tropopause to FL550+. Jet operations near the tropopause risk entering anvil cirrus (turbulence, icing) especially if CBs are embedded in cloud layers. Tropical flight planning must account for higher tropopause levels.', reference: 'CASA AMET Syllabus / Meteorology Study Guide' },
    { question: 'What is a Low Level Wind Shear (LLWS) alert and how is it generated?', options: ['A. LLWS is measured by aircraft radar only', 'B. LLWS alerts are generated by ground-based anemometer arrays (LLWAS) that detect wind speed/direction differences between stations around the aerodrome — ATC broadcasts the alert to arriving and departing crews', 'C. LLWS alerts are issued by the Bureau of Meteorology only', 'D. LLWS only affects flights below 500 ft AGL'], correct: 1, explanation: 'The Low Level Wind Shear Alert System (LLWAS) uses multiple anemometers around the aerodrome to detect wind shear. When sensors detect significant differences (indicating a microburst or frontal shear), ATC broadcasts the alert to pilots. Example: "Wind shear alert, loss of 30 kt on final 3 mile." PIREPs from preceding crews are also critical.', reference: 'CASA AMET Syllabus / AIP ENR 1.1' },
    { question: 'What is the significance of interpreting volcanic ash forecasts for ATPL operations?', options: ['A. Volcanic ash is only a concern within 100 nm of an active volcano', 'B. Volcanic ash clouds can travel thousands of nm at cruise altitude and are invisible on weather radar — ash causes severe engine damage, abrasion to windscreens, and blockage of pitot-static ports. SIGMET and VAAC charts must be monitored on affected routes', 'C. Volcanic ash only affects piston aircraft engines', 'D. Modern jet engines are unaffected by volcanic ash'], correct: 1, explanation: 'Volcanic ash is a critical hazard for jet aircraft. Fine ash particles melt in the hot engine compressor and re-solidify in cooler sections, blocking fuel nozzles and potentially causing engine flameout. The ash is invisible to weather radar and to the eye (often appears as a clear or slightly hazy area). Multiple Boeing 747 events (including KLM 867, 1989) demonstrate the severity. SIGMETs and Volcanic Ash Advisory Centre (VAAC) charts must be monitored.', reference: 'CASA AMET Syllabus / ICAO Doc 9691 / AIP ENR' },
  ],

  'Navigation Advanced': [
    { question: 'An aircraft is at FL370 with OAT -42°C. ISA at FL370 is -54.6°C. What is the approximate true altitude if the indicated altitude is 37,000 ft?', options: ['A. 37,000 ft — same as indicated', 'B. Approximately 38,550 ft', 'C. Approximately 35,450 ft', 'D. True altitude cannot be calculated without DME'], correct: 1, explanation: 'OAT = -42°C. ISA at FL370 = -54.6°C. Deviation = -42 - (-54.6) = +12.6°C warmer than ISA. Warmer = true altitude HIGHER. Correction ≈ 4 ft per 1°C per 1000 ft altitude: 4 x 12.6 x 37 = 1865 ft. True altitude ≈ 37,000 + 1865 ≈ 38,865 ft ≈ 38,550 ft (closest). A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Navigation Study Guide' },
    { question: 'A flight departs Sydney (AEST UTC+10) at 2200 local Wednesday and arrives in London (BST UTC+1) after 22 hours flight time. What is the local arrival time and day in London?', options: ['A. 1100 Thursday BST', 'B. 1100 Friday BST', 'C. 2100 Thursday BST', 'D. 0900 Friday BST'], correct: 0, explanation: 'Departure: 2200 AEST Wednesday = 1200 UTC Wednesday. Flight time: 22 hours. Arrival UTC: 1200 + 2200 = 1000 UTC Thursday. Convert to BST (UTC+1): 1000 + 0100 = 1100 BST Thursday. Answer: 1100 Thursday BST. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Time Zone Conversions' },
    { question: 'What is the Critical Point (CP) and what is the formula for calculating it?', options: ['A. The highest terrain point on the route', 'B. The point equidistant in time from two aerodromes: CP distance from A = D x GS(B) / (GS(A) + GS(B)). At the CP, time to A equals time to B', 'C. The point of minimum fuel on the route', 'D. The highest altitude point during the flight'], correct: 1, explanation: 'Critical Point (Equal Time Point): D(A to CP) = Total Distance x GS(back to A) / (GS to B + GS back to A). Example: D = 1000 nm, GS to B = 450 kt, GS back to A = 500 kt. CP = 1000 x 500 / (450+500) = 500,000 / 950 = 526 nm from A. At the CP, time to A = time to B. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Navigation Study Guide' },
    { question: 'What is the Point of No Return (PNR) and how is it calculated?', options: ['A. PNR and CP are the same calculation', 'B. PNR is the furthest point from which the aircraft can return to the departure aerodrome with required fuel reserves. Formula: PNR = (Endurance x GS back) / (GS out + GS back)', 'C. PNR is determined only by minimum diversion fuel', 'D. PNR equals the CP for all practical purposes'], correct: 1, explanation: 'PNR (Point of Safe Return): distance from departure = (Fuel endurance in hours x GS back to departure) / (GS out + GS back). Example: endurance 8 hr, GS out 480 kt, GS back 520 kt. PNR = (8 x 520) / (480+520) = 4160 / 1000 = 4.16 hr x 480 = 1997 nm from departure. Past the PNR, insufficient fuel to return. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Navigation Study Guide' },
    { question: 'What are the two key properties of a gyroscope and how do they relate to the DI?', options: ['A. Gyroscopes only have one useful property — rigidity', 'B. Rigidity in space (spin axis resists change) and precession (applied force causes movement 90° later in direction of spin). Rigidity provides the stable reference for the DI; precession causes apparent wander and is used to control erection mechanisms', 'C. Gyroscope properties are identical to compass properties', 'D. The DI does not use gyroscope principles'], correct: 1, explanation: 'Gyroscope: (1) Rigidity — spinning gyro maintains orientation in inertial space. (2) Precession — a force applied to the rim causes the gyro to move 90° later in the direction of rotation. The DI uses rigidity as its stable heading reference. Real wander (bearing imperfection) and apparent wander (earth\'s rotation) cause the DI to drift from magnetic north, requiring periodic realignment. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Navigation Study Guide' },
    { question: 'What are the radio propagation characteristics of HF waves and why are they used for long-range communications?', options: ['A. HF waves travel line-of-sight like VHF', 'B. HF waves (3-30 MHz) are refracted by the ionosphere and return to earth (skywave propagation), enabling communications over thousands of nm. The usable frequency depends on time of day, season, and solar activity — higher frequencies during day, lower at night', 'C. HF waves are absorbed by the ionosphere and cannot travel far', 'D. HF has less range than VHF because of the lower frequency'], correct: 1, explanation: 'HF (3-30 MHz) uses ionospheric refraction (skywave) for long-range communications. During the day, higher frequencies (14-22 MHz) are usable as the F-layer is more ionised. At night, the D and E layers recombine, allowing skywave propagation on lower frequencies (3-10 MHz). HF is essential for oceanic communications where VHF line-of-sight is insufficient. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / Navigation Study Guide / AIP ENR' },
    { question: 'An aircraft has TAS 450 kt, wind 270°/40 kt, tracking 360°T. What is the approximate groundspeed?', options: ['A. 410 kt', 'B. 450 kt', 'C. 490 kt', 'D. 460 kt'], correct: 2, explanation: 'Track 360°T (north), wind from 270° (westerly). A westerly wind on a northbound track is a pure crosswind with no headwind or tailwind component. Groundspeed = TAS modified by the wind component along track. For 270° wind and 360° track: wind component along track ≈ 0. GS ≈ TAS = 450 kt. Wait — the wind from 270° on a track of 360° has some component. Wind component along track = 40 x cos(90°) = 0. GS = 450 kt. Answer B. But there is a crosswind requiring a drift correction. A common weak area in ANAV — W/V calculations.', reference: 'CASA ANAV Syllabus / Navigation Study Guide' },
    { question: 'What is RNAV and what navigation accuracy (RNP) is required for RNAV approaches in Australia?', options: ['A. RNAV only uses VOR/DME and cannot be used for approaches', 'B. RNAV (Area Navigation) allows aircraft to fly any desired path using onboard navigation systems (GPS, DME/DME, VOR/DME). Australian RNAV approaches use GNSS with RNP values typically RNP 0.3 (± 0.3 nm 95% of the time) or better', 'C. RNAV requires no accuracy specification', 'D. RNAV approaches are only available above FL100'], correct: 1, explanation: 'RNAV uses onboard computers with multiple input sensors (GPS, DME/DME) to allow navigation on any path. Required Navigation Performance (RNP) specifies the accuracy and integrity. Australian RNAV/GNSS approaches: LNAV (RNP 0.3), LNAV/VNAV, LP, LPV. The aircraft and avionics must be certified for the specific approach type and RNP value.', reference: 'CASA ANAV Syllabus / AIP ENR 1.5' },
    { question: 'What is RVSM and what are the requirements for operation in RVSM airspace?', options: ['A. RVSM is applicable to all aircraft automatically', 'B. RVSM (Reduced Vertical Separation Minima) reduces separation from 2000 ft to 1000 ft in FL290-FL410 — requires aircraft with two accurate altimetry systems, AFCS maintaining ±65 ft, altitude alert, accurate Mode C, and CASA operator approval', 'C. RVSM only applies above FL410', 'D. RVSM approval is automatic with an ATPL'], correct: 1, explanation: 'RVSM airspace (FL290-FL410 in Australia, worldwide in designated areas) requires: two independent altimetry systems (accurate to ±65 ft), AFCS capable of maintaining altitude ±65 ft, altitude alert system, Mode C transponder meeting accuracy requirements, and CASA-approved RVSM operational approval for the operator. Non-RVSM approved aircraft are restricted from FL290-FL410.', reference: 'CASR Part 91 / AIP ENR 1.7 / CASA ANAV Syllabus' },
    { question: 'What is the Lowest Safe Altitude (LSALT) at the ATPL level and how is the grid LSALT on ERC HIGH used?', options: ['A. ATPL LSALT is the same as CPL LSALT', 'B. Grid LSALT on ERC HIGH is the lowest safe altitude within each 1° x 1° latitude/longitude grid providing 1000 ft clearance over all obstacles — the pilot selects the highest grid LSALT from all grids crossed on the route, including 50% of grids in the final departure/arrival', 'C. Grid LSALT only applies over the ocean', 'D. ERC HIGH charts do not publish LSALT values'], correct: 1, explanation: 'ERC HIGH grid LSALT guarantees 1000 ft obstacle clearance within each 1° x 1° grid square. Route planning: identify all grids crossed, select the highest grid LSALT value — this becomes the route LSALT. Additional considerations: 50% of adjacent grids for off-track deviations, and area MSA for en-route emergencies. A common weak area in ANAV.', reference: 'CASA ANAV Syllabus / ERC HIGH chart legend / AIP ENR' },
  ],

  'Flight Planning Advanced': [
    { question: 'What is the fuel planning requirement for an ATPL-level IFR flight under Part 121 with a designated alternate?', options: ['A. Same as Part 91 — trip fuel plus 45 minutes', 'B. Trip fuel + contingency (5% or 5 min) + alternate fuel (missed approach at destination + fly to alternate + approach) + final reserve (30 min jet at holding speed at 1500 ft at destination) + additional discretionary fuel', 'C. Trip fuel plus 1 hour reserve only', 'D. Part 121 fuel requirements are identical to Part 91'], correct: 1, explanation: 'Part 121 IFR fuel planning (jet): trip fuel + contingency (greater of 5% or 5 min at cruise) + alternate fuel (missed approach at destination, fly to alternate, conduct approach and land) + final reserve (30 min at holding speed at 1500 ft AGL at destination altitude) + additional fuel as required. Each element calculated separately without intermediate rounding.', reference: 'CASR Part 121 MOS / CAO 20.9 / CASA AAFP Syllabus' },
    { question: 'What is a WAT limit and how does it affect ATPL operations?', options: ['A. WAT limit is only relevant for propeller aircraft', 'B. WAT (Weight, Altitude, Temperature) limit is the maximum takeoff weight that allows the aircraft to meet required climb gradients with one engine inoperative — the actual MTOW for a given departure may be less than the structural MTOW if density altitude or obstacles limit climb performance', 'C. WAT limits are only published for twin-engine jets', 'D. WAT limits only apply to overwater operations'], correct: 1, explanation: 'The WAT limit constrains MTOW when density altitude (hot/high conditions) reduces OEI climb gradient below required minimums. The performance-limited MTOW may be less than the structural MTOW. ATPL operators must calculate WAT-limited MTOW from performance charts for every departure. This is a common calculation in AAFP.', reference: 'CASR Part 121 / CASA AAFP Syllabus / Performance Study Guide' },
    { question: 'What is the net takeoff flight path and how is it used for obstacle clearance?', options: ['A. The net path is the actual measured aircraft performance', 'B. The net takeoff flight path is the gross flight path reduced by a safety margin (1.2% for two-engine, 1.4% for three-engine, 1.6% for four-engine) — all obstacles must be cleared by at least 35 ft on the net path', 'C. The net path is only relevant for visual departures', 'D. Obstacles must be cleared by 200 ft on the net path'], correct: 1, explanation: 'The net takeoff flight path = gross (actual) path minus the applicable safety margin (varying by engine count). All obstacles within the obstacle accountability area must be cleared by at least 35 ft vertically (or 300 ft laterally if within the turn segment) on the NET path. This accounts for performance variability and pilot technique differences.', reference: 'CASR Part 121 / CASA AAFP Syllabus / Performance Study Guide' },
    { question: 'What is V1, Vr, and V2 and what are their relationships?', options: ['A. V1 = Vr = V2 for all aircraft', 'B. V1 (decision speed — at V1 takeoff must continue); Vr (rotation speed — below V2 must not precede V1); V2 (takeoff safety speed at screen height — minimum OEI climb gradient speed). V1 ≤ Vr ≤ V2', 'C. V2 is always greater than Vmo', 'D. These speeds only apply to three-engine aircraft'], correct: 1, explanation: 'V1: decision speed — if engine fails before V1, reject; if at/after V1, continue. Vr: rotation speed — must be ≥ V1. V2: takeoff safety speed at screen height (35 ft) — minimum speed for required OEI climb gradient. Relationship: V1 ≤ Vr ≤ V2. V2 is the speed maintained during initial climb until acceleration altitude. A common weak area in AAFP.', reference: 'CASR Part 121 / CASA AAFP Syllabus / Performance Study Guide' },
    { question: 'What is ETOPS fuel planning and what additional fuel is required?', options: ['A. ETOPS fuel planning is identical to standard IFR fuel planning', 'B. ETOPS planning requires additional fuel for the diversion from the Equal Time Point to the ETOPS alternate — fuel must account for single-engine cruise (higher burn), pressurisation loss (lower altitude cruise), plus weather reserves at the alternate', 'C. ETOPS requires only 10% additional fuel over standard planning', 'D. ETOPS fuel planning is only required for three-engine aircraft'], correct: 1, explanation: 'ETOPS fuel planning: at the most critical point (ETP from ETOPS alternate), the aircraft must have sufficient fuel to divert to the ETOPS alternate at single-engine cruise altitude (lower, hence longer time), allowing for: holding (if required), single-engine approach and landing, alternate weather, pressurisation failure descent (lower altitude = more drag), and anti-ice operations.', reference: 'CASR Part 121 / CASA AAFP Syllabus / ICAO Annex 6 ETOPS' },
    { question: 'What is the maximum landing weight (MLW) and why might it be less than maximum takeoff weight?', options: ['A. MLW equals MTOW for all aircraft', 'B. MLW is the maximum structural weight at touchdown — it is typically less than MTOW because landing loads (sink rate, hard landing) generate different stress patterns than takeoff loads. Aircraft must not exceed MLW at landing', 'C. MLW is only relevant for carrier-based aircraft', 'D. MLW limits only apply if structural damage has occurred'], correct: 1, explanation: 'MLW is set by the structural stress of landing loads rather than flight loads. The design assumption is a specific sink rate at MLW. Landing overweight generates excessive loads on landing gear and wing attach structures. If an aircraft must land overweight (emergency, fuel jettison unavailable), a structural inspection is required. Some aircraft have fuel jettison systems to reduce weight.', reference: 'CASR / AFM / CASA AAFP Syllabus' },
    { question: 'What is a balanced field length and how is V1 selected to achieve it?', options: ['A. Balanced field length means equal runway on each side of the aircraft', 'B. Balanced field length is where the accelerate-stop distance equals the takeoff distance — V1 is selected so that if an engine fails at V1, the distance to stop equals the distance to fly to screen height. This maximises V1 for the available runway', 'C. Balanced field length always equals TODA', 'D. V1 for balanced field is always the same regardless of conditions'], correct: 1, explanation: 'Balanced field: ASD (accelerate to V1, reject, stop) = TOD (accelerate to V1, continue on one engine to screen height). This is the optimum V1 — higher V1 increases ASD but decreases TOD; lower V1 decreases ASD but increases TOD. The balanced V1 maximises the useful V1 for a given runway length. A common weak area in AAFP.', reference: 'CASR Part 121 / CASA AAFP Syllabus / Performance Study Guide' },
    { question: 'What is obstacle clearance during departure and what is the minimum gradient required?', options: ['A. There are no obstacle clearance requirements for departure under Part 121', 'B. Part 121 requires the net takeoff flight path to clear all obstacles within the obstacle accountability area by at least 35 ft. The required minimum OEI net climb gradient is 2.4% for twin-engine aircraft at the end of the takeoff distance', 'C. The minimum gradient is 3.3% at all times', 'D. Obstacle clearance is only required in IMC'], correct: 1, explanation: 'CASR Part 121 departure obstacle clearance: all obstacles in the obstacle accountability area (±90 m plus half wingspan for straight, wider for turns) must be cleared by at least 35 ft on the NET one-engine-inoperative flight path. Required net climb gradients: 1st segment (gear retraction to flap retraction) 2.4% (twin), 2nd segment (gear up, flap takeoff to acceleration altitude) 2.4% (twin), final segment (all up) 1.2% (twin).', reference: 'CASR Part 121 / CASA AAFP Syllabus / Performance Study Guide' },
    { question: 'What is the significance of the accelerate-stop distance available (ASDA) on a runway?', options: ['A. ASDA is the same as TODA', 'B. ASDA is the TORA plus any stopway — it is the distance available to accelerate to V1 and bring the aircraft to a complete stop. V1 must be selected so that ASD does not exceed ASDA', 'C. ASDA only applies to wet runways', 'D. ASDA is not used in performance planning'], correct: 1, explanation: 'ASDA = TORA + stopway (a paved area beyond the runway end that can support the aircraft weight during a rejected takeoff but may not be suitable for normal operations). V1 is selected so the ASD (accelerate to V1 + stop) ≤ ASDA. A longer stopway increases ASDA and may allow a higher V1, improving continued takeoff performance.', reference: 'CASR Part 121 / CASA AAFP Syllabus / ICAO Annex 14' },
    { question: 'What is the purpose of a takeoff alternate and when is one required?', options: ['A. A takeoff alternate is the same as a destination alternate', 'B. A takeoff alternate is required when departure aerodrome weather is below landing minima — it must be within the range that can be reached if an engine fails immediately after takeoff, with required fuel to divert and land', 'C. A takeoff alternate is required for all IFR departures', 'D. Takeoff alternates are only required for oceanic departures'], correct: 1, explanation: 'A takeoff alternate is required when the departure aerodrome weather is below the operator\'s landing minima. The aircraft must be able to reach the takeoff alternate with one engine inoperative (typically within 1 hour at single-engine cruise, or for twin-jets, within 60 minutes). The alternate must have weather forecast above its own minima for the planned arrival time.', reference: 'CASR Part 121 / CAO 20.9 / CASA AAFP Syllabus' },
  ],

  'Air Law Advanced': [
    { question: 'Under CASR Part 121, what are the requirements for a valid maintenance release before departure?', options: ['A. The PIC can self-certify airworthiness', 'B. A valid MR must be in force — signed by authorised certifying staff, all defects either rectified or formally deferred per the MEL with all conditions satisfied, and not expired by any time/cycle/calendar limit', 'C. A verbal approval from the chief engineer is sufficient', 'D. MR is only required after scheduled maintenance'], correct: 1, explanation: 'Under CASR Part 42/121, a valid Maintenance Release must be in force before any flight. Requirements: signed by an authorised LAME/AME, all known defects either rectified or deferred per MEL (with all O and M procedures completed), and valid (not expired). Operating without a valid MR is illegal. A common weak area in AALW.', reference: 'CASR Part 42 / Part 121 / CASA AALW Syllabus' },
    { question: 'The AALW exam requires an 80% pass mark. What broader legal principle does this reflect?', options: ['A. It reflects that air law questions are easier', 'B. Air law underpins all legal flight operations — ATPL holders exercise command authority over large passenger transport aircraft and must demonstrate a high standard of regulatory knowledge to protect the public interest', 'C. 80% is the standard pass mark for all ATPL exams', 'D. The 80% requirement is an administrative error'], correct: 1, explanation: 'AALW requires 80% (as does CLWA at CPL level) because regulatory knowledge is the foundation of safe legal operations. ATPL holders are ultimately responsible for flights carrying hundreds of passengers. A higher knowledge standard reduces the risk of inadvertent regulatory breaches that compromise safety.', reference: 'CASA AALW Syllabus / CASR' },
    { question: 'What are the CASR defect reporting requirements for a Part 121 operator following a serious incident?', options: ['A. Only incidents causing flight cancellations require reporting', 'B. Serious incidents (as defined in CASR) must be notified to ATSB immediately (or as soon as practicable) and preserved evidence must be maintained — CASA also has separate mandatory reporting requirements for specific occurrence categories', 'C. All defects must be reported to CASA within 72 hours', 'D. Defect reporting is purely at the operator\'s discretion'], correct: 1, explanation: 'Serious incidents (as defined in CASR and ICAO Annex 13) must be notified to ATSB immediately. The operator must preserve all evidence (FDR, CVR data, aircraft, documents) and not release the aircraft for flight without ATSB authorisation. CASA has separate mandatory reportable occurrences under CAR 1988. A common weak area in AALW.', reference: 'CASR Part 11 / ATSB Act / CASA AALW Syllabus' },
    { question: 'What recency requirements must an ATPL holder meet for IFR command?', options: ['A. Only a valid medical is required', 'B. Recent IFR flight experience including instrument approaches within 90 days, regular proficiency checks as required by the operator, and valid instrument rating currency under CASR Part 61', 'C. An ATPL never requires recency — the licence is permanent', 'D. Only 3 takeoffs and landings in 90 days'], correct: 1, explanation: 'ATPL IFR recency: instrument rating current (IPC within 12 months), instrument approach currency (3 approaches within 90 days or as specified by operator), operator proficiency checks (typically every 6 months under Part 121 for line checks, and annual/biennial for base checks), and medical currency. A common weak area in AALW.', reference: 'CASR Part 61 / Part 121 / CASA AALW Syllabus' },
    { question: 'What documentation must a Part 121 aircraft carry on an international flight?', options: ['A. Only the Certificate of Airworthiness', 'B. Certificate of Airworthiness, Certificate of Registration, Radio Station Licence, Operations Specifications, crew licences and medicals, journey log, aircraft maintenance release, noise certificate, and ICAO-required documents (General Declaration for international)', 'C. Digital copies of documents satisfy all requirements', 'D. Documentation is only required for flights to non-ICAO states'], correct: 1, explanation: 'International Part 121 flights require: all standard documents plus ICAO-required documents. ICAO Annex 6 requires: noise certification document, aircraft radio station licence (ICAO format), crew licence copies (when requested), General Declaration, passenger manifest, and cargo documentation. A common weak area in AALW — documentation requirements.', reference: 'CASR Part 91 / Part 121 / ICAO Annex 6 / CASA AALW Syllabus' },
    { question: 'What are the requirements for operating in RVSM airspace under CASR?', options: ['A. Any aircraft with an altimeter can operate in RVSM airspace', 'B. Aircraft must have RVSM approval (two accurate altimetry systems, AFCS ±65 ft, altitude alert, Mode C) and the operator must hold CASA RVSM operational approval — non-approved aircraft are excluded from FL290-FL410', 'C. RVSM approval is automatic with an ATPL', 'D. RVSM only applies above FL410'], correct: 1, explanation: 'RVSM (FL290-FL410) reduces vertical separation to 1000 ft. Aircraft requirements: two independent altimetry systems accurate to ±65 ft, AFCS maintaining altitude ±65 ft, altitude alerting system, Mode C transponder meeting accuracy standards. Operator must hold CASA RVSM operational approval. A common weak area in AALW.', reference: 'CASR Part 91 / AIP ENR 1.7 / CASA AALW Syllabus' },
    { question: 'What flight and duty time limitations apply under CAO 48.1 for two-pilot airline operations?', options: ['A. No regulatory limits apply for two-pilot crews', 'B. CAO 48.1 prescribes maximum flight duty periods (typically 12-13 hours for day/early start with up to 4 sectors), minimum rest periods (10 hours for short duty or 12 hours for longer duties), and maximum cumulative limits (100 hrs/28 days, 1000 hrs/year)', 'C. Pilots can fly unlimited hours provided they feel fit', 'D. Only a maximum of 8 flight hours per day applies'], correct: 1, explanation: 'CAO 48.1 prescribes: maximum FDP varies by start time and number of sectors (typically 11-13 hrs); minimum rest between duties (10-12 hrs); maximum cumulative flight time (100 hrs/28 days, 1000 hrs/year); split duty and augmented crew provisions. Operators may also use approved FRMS for greater operational flexibility. A common weak area in AALW.', reference: 'CAO 48.1 Instrument 2019 / CASR Part 121 / CASA AALW Syllabus' },
    { question: 'What is an Airworthiness Directive (AD) and what is the legal obligation on an operator?', options: ['A. ADs are optional safety recommendations', 'B. An AD is mandatory airworthiness action issued by CASA or a foreign authority — operators MUST comply within the specified time frame. Non-compliance renders the aircraft unairworthy and the operation illegal', 'C. ADs can be deferred indefinitely under the MEL', 'D. ADs only apply to aircraft over 5700 kg'], correct: 1, explanation: 'ADs are legally mandatory under CASR Part 39. Emergency ADs may require compliance before next flight. Standard ADs specify compliance by a date, flight hours, cycles, or calendar limit. Non-compliance makes the aircraft unairworthy. Operators must have systems to receive and track AD compliance. A common weak area in AALW.', reference: 'CASR Part 39 / CASA AALW Syllabus' },
    { question: 'What are the requirements for Category II ILS operations under CASR?', options: ['A. Any aircraft with an ILS receiver can conduct Cat II', 'B. Cat II requires: aircraft type certification for Cat II, specific avionics (dual autopilot/HUD), CASA operator approval, crew Cat II training and currency, and aerodrome Cat II facility certification — all elements must be simultaneously available', 'C. Cat II approval is automatic with an ATPL', 'D. Cat II only requires a serviceable ILS and RVR 200 m'], correct: 1, explanation: 'Category II ILS (DH 100-200 ft, RVR 300-350 m): requires aircraft certification for Cat II (specific avionics, autoland or HUD), CASA operator Cat II operational approval, crew training and currency (recent Cat II approaches within qualification period), and aerodrome with Cat II certified ILS and lighting. All must be simultaneously valid. A common weak area in AALW.', reference: 'CASR Part 121 / AIP ENR 1.5 / CASA AALW Syllabus' },
    { question: 'What are the legal requirements for a pilot to maintain an ATPL under CASR?', options: ['A. The ATPL never expires and requires no maintenance', 'B. The ATPL requires: current Class 1 medical, current aircraft type rating for the aircraft being operated, current instrument rating, recency (3 takeoffs/landings in 90 days plus IFR recency), and operator-required proficiency checks — without all elements, ATPL privileges cannot be exercised', 'C. Only a valid medical is required to maintain an ATPL', 'D. Annual CASA test required to maintain ATPL'], correct: 1, explanation: 'Exercising ATPL privileges requires: valid Class 1 medical, current type rating (biennial or annual base check plus line checks under Part 121), current instrument rating (IPC within 12 months), recency requirements, and compliance with all applicable CASR Part 61 currency requirements. Failure of any element means ATPL privileges cannot be legally exercised. A common weak area in AALW.', reference: 'CASR Part 61 / Part 121 / CASA AALW Syllabus' },
  ],

  // ─── IREX ───────────────────────────────────────────────────
  'Instrument Rating': [
    { question: 'What are the ILS approach categories and their minima?', options: ['A. Categories differ only in required aircraft equipment', 'B. Cat I: DH 200 ft min, RVR 550 m; Cat II: DH 100-200 ft, RVR 300-350 m; Cat IIIa: DH below 100 ft, RVR 200 m; Cat IIIb: DH below 50 ft, RVR 75 m — each requires progressively more sophisticated equipment and training', 'C. All categories have the same decision height', 'D. Cat III has higher DH than Cat I'], correct: 1, explanation: 'ILS categories: Cat I (DH 200 ft, RVR 550 m), Cat II (DH 100-200 ft, RVR 300-350 m), Cat IIIa (DH below 100 ft, RVR 200 m), Cat IIIb (DH below 50 ft, RVR 75 m), Cat IIIc (no DH or RVR). Each requires certified aircraft equipment, aerodrome facilities, and crew qualification.', reference: 'ICAO Doc 8168 / AIP ENR 1.5 / CASA IREX Syllabus' },
    { question: 'What is a circling approach and what limitations apply?', options: ['A. A circling approach is the same as a straight-in approach', 'B. A circling approach is used when landing on a different runway than the published approach — the aircraft descends to circling MDA, establishes visual contact, and manoeuvres visually to land. The circling area radius depends on aircraft category (Cat B: 2.66 nm)', 'C. Circling is prohibited in IMC', 'D. No limitations apply to circling approaches'], correct: 1, explanation: 'A circling approach is used when the approach alignment does not permit a straight-in landing on the intended runway. The aircraft descends to circling MDA (higher than straight-in) and circles visually. Circling areas: Cat A 1.68 nm, Cat B 2.66 nm, Cat C 4.2 nm. If visual reference is lost during circling, execute an immediate missed approach.', reference: 'ICAO Doc 8168 / AIP ENR 1.5 / CASA IREX Syllabus' },
    { question: 'What is the purpose of a procedure turn on a non-precision approach?', options: ['A. Always mandatory on all approaches', 'B. A procedure turn reverses the aircraft direction to intercept the inbound final approach course — it may be omitted when "NoPT" is published, when ATC radar vectors to final, or when arriving via a routing that does not require it', 'C. Only required in IMC', 'D. Only used on NDB approaches'], correct: 1, explanation: 'A procedure turn (PT) is a manoeuvre to reverse direction and establish inbound on the final approach course. It is required unless: chart states "NoPT", pilot is radar vectored to final, or arriving via a published route that aligns with the approach. When required, it must be completed within the specified distance from the fix.', reference: 'ICAO Doc 8168 / AIP ENR 1.5 / CASA IREX Syllabus' },
    { question: 'What is the STAR (Standard Terminal Arrival Route) and what are crew obligations when cleared for one?', options: ['A. A STAR is a suggested routing only', 'B. A STAR is a published IFR arrival connecting the en-route structure to the IAF — crews must comply with all published lateral routing and altitude/speed restrictions unless amended by ATC', 'C. A STAR only applies to jet aircraft', 'D. STAR clearance means fly direct to destination'], correct: 1, explanation: 'A STAR is an approved IFR arrival procedure. When cleared "via STAR", comply with all published constraints (lateral routing, altitude restrictions, speed limits) unless ATC issues specific amendments. ATC may issue direct routing, altitude changes, or speed control that supersedes published constraints.', reference: 'AIP ENR 1.1 / ICAO Doc 4444 / CASA IREX Syllabus' },
    { question: 'What are the IFR fuel requirements under Part 91 with a nominated alternate?', options: ['A. Trip fuel plus 45 minutes only', 'B. Trip fuel + contingency (5% or 5 min, whichever greater) + alternate fuel (missed approach + fly to alternate + approach) + final reserve (45 min piston or 30 min jet holding at 1500 ft at destination)', 'C. Trip fuel plus 1 hour reserve only', 'D. Same as VFR requirements'], correct: 1, explanation: 'IFR fuel under Part 91/CAO 20.9: trip fuel + contingency (greater of 5% trip or 5 min at cruise) + alternate fuel (missed approach at destination, cruise to alternate, approach and land) + final reserve (45 min piston / 30 min turbine at holding speed at 1500 ft AGL at destination). Each element calculated separately.', reference: 'CASR Part 91 / CAO 20.9 / CASA IREX Syllabus' },
    { question: 'What is an NDB and how does the ADF work?', options: ['A. NDB transmits a directional signal toward the runway', 'B. NDB transmits an omnidirectional LF/MF carrier wave — the ADF needle points TO the NDB from any position, allowing tracking to/from the beacon and position fixing. NDBs are susceptible to thunderstorm interference, coastal refraction, and night effect', 'C. NDB provides both distance and bearing', 'D. NDBs only work for en-route navigation'], correct: 1, explanation: 'NDB (Non-Directional Beacon) transmits omnidirectionally on LF/MF (190-1750 kHz). The ADF (Automatic Direction Finder) needle points TO the station. The pilot can track to the NDB, track away from it, or use two NDB bearings for a fix. NDB errors: thunderstorm interference (pointer swings toward lightning), coastal refraction, and night effect (ionospheric reflection at night).', reference: 'AIP ENR 4.1 / CASA IREX Syllabus' },
    { question: 'What is an RNAV (GNSS) approach and what are the variants available?', options: ['A. RNAV approaches only use VOR/DME', 'B. RNAV(GNSS) approaches use satellite navigation — variants include: LNAV (lateral only, MDA), LNAV/VNAV (lateral + baro vertical, DA), LP (precision lateral, MDA), LPV (lateral precision + vertical, DA similar to Cat I ILS)', 'C. RNAV approaches have no accuracy requirements', 'D. RNAV only available at international aerodromes'], correct: 1, explanation: 'RNAV(GNSS) approach variants: LNAV — GPS lateral guidance only (like NDB/VOR), uses MDA. LNAV/VNAV — lateral plus barometric vertical, uses DA. LP — precision lateral (like LOC), uses MDA. LPV — Localiser Performance with Vertical guidance (approaching Cat I ILS quality), uses DA with typical minima 200 ft and 550 m RVR. Aircraft must be certified for each type.', reference: 'AIP ENR 1.5 / ICAO Doc 8168 / CASA IREX Syllabus' },
    { question: 'What action if both ILS glideslope and localiser flags appear in IMC?', options: ['A. Continue using standby instruments', 'B. Execute immediate missed approach — both ILS components have failed, no electronic approach guidance remains. Declare PAN or MAYDAY and advise ATC', 'C. Descend to MDA and continue visually', 'D. Continue approach using raw data backup'], correct: 1, explanation: 'If ILS flags appear (unreliable/failed signal), the approach must be immediately abandoned. With both GS and LOC flagged in IMC, no instrument guidance exists for the approach. Execute the published missed approach immediately, declare PAN/MAYDAY as appropriate, advise ATC, and request an alternative approach procedure or diversion.', reference: 'ICAO Doc 8168 / AIP ENR 1.5 / FCOM emergency procedures' },
    { question: 'What is the minimum descent altitude (MDA) on a non-precision approach?', options: ['A. MDA is the same as Decision Altitude', 'B. MDA is the lowest altitude to which the aircraft may descend on a non-precision approach without the required visual reference — unlike DA (where missed approach is initiated at the DA), the aircraft may fly level at MDA to acquire visual reference before initiating missed approach at the missed approach point', 'C. MDA is only applicable for NDB approaches', 'D. MDA is the altitude at which autopilot must disconnect'], correct: 1, explanation: 'On non-precision approaches (VOR, NDB, RNAV LNAV), the aircraft descends to MDA and levels off. The pilot may fly level at MDA until the missed approach point (MAP) to acquire the required visual reference. Unlike DA (where missed approach begins immediately at DA without visual), the pilot at MDA can continue to the MAP at MDA. If visual not acquired at MAP, execute missed approach.', reference: 'ICAO Doc 8168 / AIP ENR 1.5 / CASA IREX Syllabus' },
    { question: 'What is required for an IFR alternate and what fuel must be carried?', options: ['A. An alternate is always required for all IFR flights', 'B. An alternate is required when destination weather is forecast below applicable approach minima during the arrival window — the alternate must have forecast weather above its own minima. Alternate fuel = missed approach at destination + cruise to alternate + approach and land', 'C. An alternate is only required for night IFR flights', 'D. Any aerodrome can be nominated as an alternate regardless of weather'], correct: 1, explanation: 'An IFR alternate is required when the destination weather is forecast below applicable minima during the planned arrival period (typically ±1 hour of ETA). The alternate must meet its own forecast weather requirements. Alternate fuel calculation: execute missed approach at destination, cruise at normal speed to alternate, conduct approach and landing — includes all these segments without intermediate rounding.', reference: 'CASR Part 91 / CAO 20.9 / CASA IREX Syllabus' },
  ],
}

function findQuestions(subject: string) {
  if (freeQuestions[subject]) return freeQuestions[subject]
  const lower = subject.toLowerCase().trim()
  for (const key of Object.keys(freeQuestions)) {
    if (key.toLowerCase().trim() === lower) return freeQuestions[key]
  }
  for (const key of Object.keys(freeQuestions)) {
    if (lower.includes(key.toLowerCase()) || key.toLowerCase().includes(lower)) return freeQuestions[key]
  }
  return []
}

function getLicence(subject: string): string {
  if (subject === 'PPL Theory') return 'PPL'
  if (subject === 'Instrument Rating') return 'IREX'
  if (['Human Factors Advanced', 'Aerodynamics Advanced', 'Aircraft General Advanced', 'Meteorology Advanced', 'Navigation Advanced', 'Flight Planning Advanced', 'Air Law Advanced'].includes(subject)) return 'ATPL'
  return 'CPL'
}

export default function QuizPage({ params }: { params: Promise<{ subject: string }> }) {
  const resolvedParams = use(params)
  const subject = decodeURIComponent(resolvedParams.subject || '')
  const [questions, setQuestions] = useState<any[]>([])
  const [currentIdx, setCurrentIdx] = useState(0)
  const [answered, setAnswered] = useState(false)
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null)
  const [finished, setFinished] = useState(false)
  const [scoreSaved, setScoreSaved] = useState(false)
  const [finalScore, setFinalScore] = useState(0)
  const scoreRef = useRef(0)

  useEffect(() => {
    if (!subject) return
    const bank = findQuestions(subject)
    const shuffled = [...bank].sort(() => Math.random() - 0.5).slice(0, 10)
    setQuestions(shuffled)
    scoreRef.current = 0
  }, [subject])

  async function saveScore(s: number, total: number) {
    try {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) return
      const pct = Math.round(s / total * 100)
      const { error } = await supabase.from('scores').insert({
        user_id: user.id,
        subject,
        licence: getLicence(subject),
        score: s,
        total,
        percentage: pct
      })
      if (!error) setScoreSaved(true)
    } catch (e) {
      console.error('Score save error:', e)
    }
  }

  function selectAnswer(idx: number) {
    if (answered) return
    setAnswered(true)
    setSelectedAnswer(idx)
    if (idx === questions[currentIdx].correct) {
      scoreRef.current += 1
    }
  }

  function nextQuestion() {
    const isLast = currentIdx >= questions.length - 1
    if (isLast) {
      const fs = scoreRef.current
      setFinalScore(fs)
      saveScore(fs, questions.length)
      setFinished(true)
    } else {
      setCurrentIdx(i => i + 1)
      setAnswered(false)
      setSelectedAnswer(null)
    }
  }

  function restart() {
    const bank = findQuestions(subject)
    setQuestions([...bank].sort(() => Math.random() - 0.5).slice(0, 10))
    setCurrentIdx(0)
    setFinalScore(0)
    setFinished(false)
    setAnswered(false)
    setSelectedAnswer(null)
    setScoreSaved(false)
    scoreRef.current = 0
  }

  if (!subject || questions.length === 0) return (
    <main style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'system-ui,sans-serif', flexDirection: 'column', gap: '1rem' }}>
      <p style={{ color: '#64748b', fontSize: '16px' }}>Loading questions...</p>
      <a href="/dashboard" style={{ color: '#2563eb', textDecoration: 'none' }}>Back to dashboard</a>
    </main>
  )

  if (finished) {
    const pct = Math.round(finalScore / questions.length * 100)
    return (
      <main style={{ minHeight: '100vh', background: '#f8fafc', fontFamily: 'system-ui,sans-serif', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem' }}>
        <div style={{ background: 'white', borderRadius: '16px', padding: '2.5rem', maxWidth: '500px', width: '100%', border: '1px solid #e2e8f0', textAlign: 'center' }}>
          <div style={{ fontSize: '13px', color: '#94a3b8', fontFamily: 'monospace', marginBottom: '8px' }}>{subject}</div>
          <div style={{ fontSize: '56px', fontWeight: '800', color: '#1e3a6e', fontFamily: 'monospace' }}>{pct}</div>
          <div style={{ fontSize: '16px', color: '#64748b', marginBottom: '8px' }}>percent</div>
          <div style={{ fontSize: '16px', fontWeight: '600', color: pct >= 70 ? '#16a34a' : '#dc2626', marginBottom: '0.5rem' }}>
            {pct >= 70 ? 'Pass — well done!' : 'Below pass mark — keep studying'}
          </div>
          {scoreSaved && <div style={{ fontSize: '12px', color: '#10b981', marginBottom: '1.5rem' }}>Score saved to your progress</div>}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '2rem' }}>
            <div style={{ background: '#f0fdf4', borderRadius: '8px', padding: '12px' }}>
              <div style={{ fontSize: '24px', fontWeight: '600', color: '#16a34a' }}>{finalScore}</div>
              <div style={{ fontSize: '12px', color: '#64748b' }}>Correct</div>
            </div>
            <div style={{ background: '#fff1f2', borderRadius: '8px', padding: '12px' }}>
              <div style={{ fontSize: '24px', fontWeight: '600', color: '#dc2626' }}>{questions.length - finalScore}</div>
              <div style={{ fontSize: '12px', color: '#64748b' }}>Incorrect</div>
            </div>
          </div>
          <div style={{ display: 'flex', gap: '8px' }}>
            <button onClick={restart} style={{ flex: 1, background: '#2563eb', color: 'white', border: 'none', borderRadius: '8px', padding: '11px', fontWeight: '600', cursor: 'pointer', fontSize: '14px' }}>Try Again</button>
            <a href="/dashboard" style={{ flex: 1, background: '#f8fafc', color: '#0a1628', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '11px', fontWeight: '600', textDecoration: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '14px' }}>Dashboard</a>
          </div>
          <a href="/progress" style={{ display: 'block', marginTop: '12px', fontSize: '13px', color: '#2563eb', textDecoration: 'none' }}>View all progress →</a>
        </div>
      </main>
    )
  }

  const q = questions[currentIdx]
  const letters = ['A', 'B', 'C', 'D']

  return (
    <main style={{ minHeight: '100vh', background: '#f8fafc', fontFamily: 'system-ui,sans-serif' }}>
      <nav style={{ background: 'white', borderBottom: '1px solid #e2e8f0', padding: '1rem 2rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div>
          <span style={{ fontSize: '20px', fontWeight: '800', color: '#2563eb' }}>V1</span>
          <span style={{ fontSize: '20px', fontWeight: '800', color: '#0a1628' }}> Study</span>
        </div>
        <a href="/dashboard" style={{ color: '#64748b', textDecoration: 'none', fontSize: '14px' }}>Back to dashboard</a>
      </nav>
      <div style={{ maxWidth: '700px', margin: '0 auto', padding: '2rem' }}>
        <div style={{ marginBottom: '6px', fontSize: '11px', color: '#94a3b8', fontFamily: 'monospace' }}>Question {currentIdx + 1} of {questions.length}</div>
        <div style={{ background: '#e2e8f0', borderRadius: '99px', height: '4px', marginBottom: '1.5rem', overflow: 'hidden' }}>
          <div style={{ height: '100%', background: '#2563eb', borderRadius: '99px', width: `${(currentIdx / questions.length) * 100}%`, transition: 'width 0.4s' }}></div>
        </div>
        <div style={{ background: 'white', borderRadius: '12px', padding: '1.5rem', border: '1px solid #e2e8f0', marginBottom: '1rem' }}>
          <div style={{ fontSize: '11px', fontWeight: '600', color: '#2563eb', marginBottom: '10px', fontFamily: 'monospace' }}>{subject}</div>
          <div style={{ fontSize: '16px', fontWeight: '600', color: '#0a1628', lineHeight: 1.55, marginBottom: '1.25rem' }}>{q.question}</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {q.options.map((opt: string, i: number) => {
              let bg = 'white'
              let border = '1px solid #e2e8f0'
              let col = '#0a1628'
              if (answered) {
                if (i === q.correct) { bg = '#f0fdf4'; border = '1px solid #16a34a'; col = '#15803d' }
                else if (i === selectedAnswer) { bg = '#fff1f2'; border = '1px solid #dc2626'; col = '#b91c1c' }
                else { col = '#94a3b8' }
              }
              return (
                <button key={i} onClick={() => selectAnswer(i)} disabled={answered} style={{ background: bg, border, borderRadius: '8px', padding: '11px 14px', textAlign: 'left', cursor: answered ? 'default' : 'pointer', fontSize: '14px', color: col, display: 'flex', alignItems: 'flex-start', gap: '10px', width: '100%' }}>
                  <span style={{ fontFamily: 'monospace', fontSize: '12px', background: answered && i === q.correct ? '#dcfce7' : answered && i === selectedAnswer ? '#ffe4e6' : '#f1f5f9', borderRadius: '4px', padding: '1px 6px', minWidth: '22px', textAlign: 'center', flexShrink: 0, marginTop: '1px' }}>
                    {answered && i === q.correct ? '✓' : answered && i === selectedAnswer ? '✗' : letters[i]}
                  </span>
                  <span>{opt.replace(/^[A-D]\.\s*/, '')}</span>
                </button>
              )
            })}
          </div>
        </div>
        {answered && (
          <div style={{ background: '#f0f7ff', border: '1px solid #bfdbfe', borderRadius: '12px', padding: '1.25rem', marginBottom: '1rem' }}>
            <div style={{ fontSize: '13px', fontWeight: '600', color: '#1d4ed8', marginBottom: '8px' }}>Explanation</div>
            <p style={{ fontSize: '13px', lineHeight: 1.65, color: '#1e3a6e', marginBottom: '12px' }}>{q.explanation}</p>
            <div style={{ borderTop: '1px solid #bfdbfe', paddingTop: '10px' }}>
              <div style={{ fontSize: '10px', fontFamily: 'monospace', color: '#2563eb', marginBottom: '4px', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Reference — verify this yourself</div>
              <div style={{ fontSize: '12px', color: '#3b82f6', fontFamily: 'monospace' }}>{q.reference}</div>
            </div>
          </div>
        )}
        {answered && (
          <button onClick={nextQuestion} style={{ width: '100%', background: '#1e3a6e', color: 'white', border: 'none', borderRadius: '8px', padding: '12px', fontSize: '15px', fontWeight: '600', cursor: 'pointer' }}>
            {currentIdx < questions.length - 1 ? 'Next question →' : 'See results →'}
          </button>
        )}
      </div>
    </main>
  )
}
